window.AUTH=window.AUTH||{};window.AUTH["19-1442"]={"d":"19-1442","id":"2020/19-1442","n":"Carr v. Saul","briefs":[{"k":"petitioner","label":"Brief of petitioners John J. Davis, Thomas Hilliard, Kimberly L. Iwan, Destiny M. Thurman (in 20-105)","date":"2020-12-28","url":"https://www.supremecourt.gov/DocketPDF/19/19-1442/164776/20201228120440193_20-105_petbr.pdf","side":"pet","n":115},{"k":"petitioner","label":"Brief of petitioners Willie Earl Carr, et al.","date":"2020-12-28","url":"https://www.supremecourt.gov/DocketPDF/19/19-1442/164787/20201228130720998_Carr%20Brief%20For%20Petitioners.pdf","side":"pet","n":62},{"k":"respondent","label":"Brief of respondent Saul, Andrew M., Commissioner of Social Security","date":"2021-01-27","url":"https://www.supremecourt.gov/DocketPDF/19/19-1442/167431/20210127200817033_19-1442bsUnitedStates.pdf","side":"res","n":80},{"k":"reply","label":"Reply of petitioners Willie Earl Carr, et al.","date":"2021-02-17","url":"https://www.supremecourt.gov/DocketPDF/19/19-1442/169199/20210217131057671_Carr%20Reply%20Brief%20of%20Petitioner.pdf","side":"pet","n":33},{"k":"reply","label":"Reply of petitioners John J. Davis, Thomas Hilliard, Kimberly L. Iwan, Destiny M. Thurman","date":"2021-02-18","url":"https://www.supremecourt.gov/DocketPDF/19/19-1442/169279/20210218133714545_20-105_meritsreply.pdf","side":"pet","n":41}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us1r29_b97c.pdf","tr":true,"items":[{"t":"case","label":"Aragon v. Unemployment Compensation Commission","cite":"149 F.2d 447","y":1945,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/149/447/","by":{"0":"31"}},{"t":"case","label":"Bethesda Hospital Association v. Bowen","cite":"485 U.S. 399","y":1988,"id":"1987/86-1764","sc":1,"op":1,"sum":"The Board may not decline to consider a provider's challenge to a regulation of the Secretary on the ground that the provider failed to contest the regulation's validity in the cost report submitted to its fiscal intermediary. The plain language of § 1395oo(a) demonstrates that the Board had jurisdiction to entertain this action. There is no merit to the Secretary's contention that a provider's right to a hearing …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38"}},{"t":"case","label":"Biestek v. Berryhill","cite":"139 S. Ct. 1148","y":2019,"id":"2018/17-1184","sc":1,"sum":"A vocational expert’s refusal to provide private market-survey data during a Social Security disability benefits hearing upon the applicant’s request does not categorically preclude the testimony from counting as “substantial evidence” in federal court under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25","3":"21"}},{"t":"case","label":"Bowen v. City of New York","cite":"476 U.S. 467","y":1986,"id":"1985/84-1923","sc":1,"sum":"The Social Security Act provides benefits to disabled persons under two programs administered by the Social Security Administration (SSA): the Social Security Disability Insurance Program (SSD) and the Supplemental Security Income Program (SSI). Regulations for both programs establish a five-step \"sequential evaluation\" process for determining eligibility for benefits. The initial determination of whether an …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 40","1":"37","2":"42","3":"3, 9, 10"}},{"t":"case","label":"Califano v. Sanders","cite":"430 U.S. 99","y":1977,"id":"1976/75-1443","sc":1,"op":1,"ar":1,"sum":"1. Section 10 of the Administrative Procedure Act (APA), providing generally for judicial review of actions of federal administrative agencies by persons aggrieved by such actions, does not afford an implied grant to district courts of subject-matter jurisdiction to review a decision of the Secretary of Health, Education, and Welfare not to reopen a previously adjudicated claim for social security benefits. An …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37, 40","1":"37","3":"9"}},{"t":"case","label":"Carr v. Commissioner","cite":"961 F.3d 1267","y":2020,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/961/1267/","op":1,"by":{"0":"29","1":"1, 21"}},{"t":"case","label":"Department of Transportation v. Public Citizen","cite":"541 U.S. 752","y":2004,"id":"2003/03-358","sc":1,"sum":"The Court held that the FMCSA had no control of the trucks once the regulations were passed, and would therefore be unable to act on the findings of an EIS even if it did conduct one. Further, the Court found that the passage of the regulations was not sufficiently responsible for the increased pollution caused by the trucks to warrant an EIS.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Elgin v. Department of Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"sum":"The Court held that the Civil Service Reform Act precludes federal courts' jurisdiction in cases where federal employees seek equitable relief.","sumSrc":"Oyez","by":{"0":"38","2":"44"}},{"t":"case","label":"Free Enterprise Fund v. Public Company Accounting Oversight Board","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"op":1,"ar":2,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"37","1":"35","3":"10, 15","4":"21"}},{"t":"case","label":"Freytag v. Commissioner","cite":"501 U.S. 868","y":1991,"id":"1990/90-762","sc":1,"sum":"On the question of whether 7443A permitted the assignment of complex cases to special trial judges, the Supreme Court unanimously ruled that the statute unambiguously did allow such appointments. Justice Harry Blackmun, in the majority opinion, wrote, \"The plain language of 7443A(b)(4) surely authorizes the Chief Judge's assignment of petitioners' cases to a special trial judge.","sumSrc":"Oyez","by":{"0":"3, 39, 44, 45","1":"39, 40","2":"18, 47","3":"23"}},{"t":"case","label":"Gibson v. Berryhill","cite":"411 U.S. 564","y":1973,"id":"1972/71-653","sc":1,"sum":"Appellees, licensed optometrists employed by Lee Optical Co., who were not members of the Alabama Optometric Association (Association), were charged by the Association with unprofessional conduct within the meaning of the state optometry statute because of their employment with the company. The complaint was filed with the Alabama Board of Optometry (Board), all members of which were Association members.,The Board …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Gutierrez de Martinez v. Lamango","cite":"515 U.S. 417","y":1995,"id":"1994/94-167","sc":1,"op":1,"sum":"Invoking the federal court's jurisdiction based on diversity of citizenship, petitioners alleged in their complaint that they had suffered physical injuries and property damage as a result of an accident in Colombia caused by the negligence of respondent Lamagno, a federal employee. The United States Attorney, acting pursuant to the statute commonly known as the Westfall Act, 28 U. S. C. §2679(d)(1), certified on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Hormel v. Helvering","cite":"312 U.S. 552","y":1941,"id":"scdb/1940-106","sc":1,"op":1,"sum":"1. Upon review of a decision of the Board of Tax Appeals that neither under § 166 nor § 167 of the Revenue Act of 1934 was the income of the trusts here involved taxable to the grantor, the Circuit Court of Appeals-Helvering v. Clifford, 309 U. S. 331, having in the meantime been decided by this Court-could properly consider the question of the grantor's liability under § 22 (a) of the Act, even though the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","1":"25, 34","2":"passim","3":"12, 14","4":"5"}},{"t":"case","label":"Island Creek Coal Co. v. Bryan","cite":"937 F.3d 738","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/937/738/","by":{"0":"31","2":"11, 12","4":"10"}},{"t":"case","label":"Lexmark International, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Little Sisters of the Poor Saints Peter & Paul Home v. Pennsylvania","cite":"140 S. Ct. 2367","y":2020,"id":"2019/19-431","sc":1,"sum":"The Court held that the federal government acted properly when it added extensive exemptions to regulations requiring employers to include contraceptive coverage in employee health plans.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Lucia v. SEC","cite":"138 S. Ct. 2044","y":2018,"id":"2017/17-130","sc":1,"sum":"The Court decided that administrative law judges of the Securities and Exchange Commission are \"officers of the United States\" subject to the Constitution's Appointments Clause.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"16, 17, 18","4":"16, 18, 19"}},{"t":"case","label":"Mathews v. Diaz","cite":"426 U.S. 67","y":1976,"id":"1974/73-1046","sc":1,"sum":"Title 42 U. S. C. § 1395o (2) qualifies for enrollment in the Medicare supplemental medical insurance program residents of the United States who are 65 or older, but in subsection (B) denies eligibility to aliens unless they have been admitted for permanent residence and also have resided in the United States for at least five years. Appellee Diaz filed a class action suit in the District Court attacking the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37, 38","1":"37","2":"42"}},{"t":"case","label":"Mathews v. Eldridge","cite":"424 U.S. 319","y":1976,"id":"1975/74-204","sc":1,"op":1,"sum":"In an 6-to-2 decision, the Court held that the initial termination of Eldridge's benefits without a hearing did not violate due process.","sumSrc":"Oyez","by":{"0":"37, 38, 43","1":"37","2":"20, 42","3":"9","4":"17"}},{"t":"case","label":"McCarthy v. Madigan","cite":"503 U.S. 140","y":1992,"id":"1991/90-6861","sc":1,"op":2,"sum":"Exhaustion of the Bureau of Prisons' administrative procedure is not required before a federal prisoner can initiate a Bivens action solely for money damages.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38, 40, 42","1":"passim","2":"15, 43","3":"11, 13"}},{"t":"case","label":"Montana National Bank of Billings v. Yellowstone County","cite":"276 U.S. 499","y":1928,"id":"scdb/1927-169","sc":1,"op":1,"sum":"1. A substantial discrimination against national banks in favor of incorporated state banks resulting from taxation of national bank shares upon a valuation equal to that of the assets of the bank, including bonds and like securities of the United States, while the shares of the state banks are not taxed and the state banks themCounsel for Parties. selves are taxed only on the value of their assets after excluding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","2":"13, 44"}},{"t":"case","label":"Myers v. Bethlehem Shipbuilding Corp.","cite":"303 U.S. 41","y":1938,"id":"scdb/1937-127","sc":1,"sum":"(1) That the District Court had no jurisdiction of a suit by the corpdration to enjoin the Board from holding the hearing. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"0":"39","1":"39"}},{"t":"case","label":"O’Leary v. OPM","cite":"708 Fed. Appx. 669","y":2017,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./708/669/","by":{"0":"9","2":"5"}},{"t":"case","label":"PDR Network, LLC v. Carlton & Harris Chiropractic, Inc.","cite":"139 S. Ct. 2051","y":2019,"id":"2018/17-1705","sc":1,"sum":"The Court held that Fourth Circuit did not properly consider preliminary issues that determine whether a district court must accept the Federal Communication Commission's legal interpretation of the Telephone Consumer Protection Act.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Perez v. Mortgage Bankers Association","cite":"135 S. Ct. 1199","y":2015,"id":"2014/13-1041","sc":1,"sum":"The Court ruled that federal agencies do not need to engage in a notice-and-comment procedure before significantly altering an interpretation of a rule of agency regulation.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Reiter v. Cooper","cite":"507 U.S. 258","y":1993,"id":"1992/91-1496","sc":1,"sum":"The Interstate Commerce Act (ICA) requires that motor common carriers charge the tariff rates they file with the Interstate Commerce Commission (ICC), 49 U. S. C. § 10762, and that such rates be \"reasonable,\" § 10701(a). Between 1984 and 1986, petitioner shippers tendered shipments to Carolina Motor Express, Inc., a motor carrier subject to ICC regulation, at negotiated rates that were lower than the applicable …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5"}},{"t":"case","label":"Richardson v. Perales","cite":"402 U.S. 389","y":1971,"id":"1970/108","sc":1,"op":3,"sum":"Written reports by physicians who have examined claimant for disability insurance benefits under Social Security Act constitute \"substantial evidence\" supporting a nondisability finding within the standard of § 205 (g) of the Act, notwithstanding the reports' hearsay character, the absence of cross-examination (through claimant's failure to exercise his subpoena rights), and the directly opposing testimony by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39","1":"24","2":"21, 23, 29, 30, 37","3":"15","4":"5"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","1":"20","4":"13"}},{"t":"case","label":"Salinas v. Texas","cite":"570 U.S. 178","y":2013,"id":"2012/12-246","sc":1,"sum":"The Court held that the Fifth Amendment's Self-Incrimination clause does not protect individuals that have not been arrested.","sumSrc":"Oyez","by":{"0":"32","3":"10"}},{"t":"case","label":"Shalala v. Illinois Council on Long Term Care, Inc.","cite":"529 U.S. 1","y":2000,"id":"1999/98-1109","sc":1,"sum":"The Court held that the Medicare Act barred federal-question jurisdiction of the Council's challenges to the validity of various Medicare regulations. The Court concluded that the Council must proceed instead through the special review channel that the Medicare statutes create.","sumSrc":"Oyez","by":{"0":"38"}},{"t":"case","label":"Sims v. Apfel","cite":"530 U.S. 103","y":2000,"id":"1999/98-9537","sc":1,"op":14,"ar":23,"sum":"The Court held, 5 to 4, that Social Security claimants who exhaust administrative remedies need not also exhaust issues administratively in order to preserve judicial review of those issues.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim","4":"passim"}},{"t":"case","label":"Singleton v. Wulff","cite":"428 U.S. 106","y":1976,"id":"1975/74-1393","sc":1,"sum":"The judgment is reversed and the case is remanded. Pp. 112-121; 121-122; 122. 508 F. 2d 1211, reversed and remanded. MR. JUSTICE BLACKMUN delivered the opinion of the Court with respect to Parts I, II-A, and III, finding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44, 45"}},{"t":"case","label":"Smith v. Berryhill","cite":"139 S. Ct. 1765","y":2019,"id":"2018/17-1606","sc":1,"sum":"A Social Security Administration Appeals Council dismissal on timeliness grounds of a request for review after a claimant has had an administrative law judge hearing on the merits qualifies as a “final decision . . . made after a hearing” for purposes of allowing judicial review under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"passim","1":"passim","2":"2, 4","3":"3, 4","4":"6, 7, 12, 14"}},{"t":"case","label":"Spiller v. Atchison, Topeka & Santa Fe Railway Co.","cite":"253 U.S. 117","y":1920,"id":"scdb/1919-076","sc":1,"sum":"In cases of a class which may ultimately reach this court by writ of error under Jud. Code, §§ 128 and 241, this court has jurisdiction to review by certiorari judgments of the Circuit Court of Appeals which are not final in the sense of concluding the litigation, such jurisdiction arising under § 262 when the jurisdictional amount prescribed by § 241 is in controversy and under § 240 when it is not.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31, 32","1":"34","2":"12"}},{"t":"case","label":"Unemployment Compensation Commission v. Aragon","cite":"329 U.S. 143","y":1946,"id":"scdb/1946-009","sc":1,"op":1,"sum":"Companies engaged in catching and canning salmon in Alaska terminated their agreement with the union representing their employees at the end of the 1939 season. Prior to the beginning of the 1940 season, they opened negotiations in San Francisco with the same union for a new agreement. There ensued a controversy over wages which resulted in a failure to reach an agreement aaid a decision to conduct no operations …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 32, 33","1":"35","2":"12, 14, 26"}},{"t":"case","label":"United States v. L.A. Tucker Truck Lines, Inc.","cite":"344 U.S. 33","y":1952,"id":"scdb/1952-007","sc":1,"op":8,"ar":5,"sum":"The district court should not entertain this objection when first made at that stage of the proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"33, 34","2":"passim","3":"12, 13, 14","4":"9, 10, 18"}},{"t":"case","label":"United States v. Northern Pacific Railway Co.","cite":"288 U.S. 490","y":1933,"id":"scdb/1932-156","sc":1,"by":{"0":"31, 32","1":"34","2":"12, 14"}},{"t":"case","label":"United States v. Sineneng-Smith","cite":"140 S. Ct. 1575","y":2020,"id":"2019/19-67","sc":1,"sum":"The Court held that the Ninth Circuit’s decision below was an abuse of discretion because it considered and ruled on an issue not raised by the parties.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"United States ex rel. Vajtauer v. Commissioner of Immigration","cite":"273 U.S. 103","y":1927,"id":"scdb/1926-142","sc":1,"sum":"1. Want of due process in.proceedings for the deportation of an alien is notestablished by showing merely that the decision was erroneous or that incompetent evidence was received and considered. P, 106,","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31, 32","1":"34","2":"12, 43","3":"10"}},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"op":1,"ar":1,"sum":"After her husband of less than six months died, appellee widow filed applications for mother's Social Security insurance benefits for herself and child's insurance benefits for her daughter by a previous marriage, but the Social Security Administration (SSA), both initially and on reconsideration at the regional level, denied the applications on the basis of the duration-of-relationship requirements of the Social …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"38","1":"37","2":"41, 42","4":"18"}},{"t":"case","label":"Woelke & Romero Framing, Inc. v. NLRB","cite":"456 U.S. 645","y":1982,"id":"1981/80-1798","sc":1,"sum":"Section 8(e) of the National Labor Relations Act (Act) proscribes secondary agreements between unions and employers-that is, agreements that require an employer to cease doing business with another party. However, § 8(e) contains a proviso which exempts from the proscription of § 8(e) agreements between a union and an employer in the construction industry concerning the contracting or subcontracting of work to be …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Woodford v. Ngo","cite":"548 U.S. 81","y":2006,"id":"2005/05-416","sc":1,"op":1,"ar":2,"sum":"In a 6-to-3 decision authored by Justice Samuel Alito, the Supreme Court held that a prisoner must properly exhaust any available administrative remedies before bringing suit in federal court. This understanding of the PLRA's exhaustion provision mirrors that of the traditional exhaustion provision in administrative law and is \"substantively similar\" to that of habeas corpus law.","sumSrc":"Oyez","by":{"0":"30, 41, 42","1":"33","2":"13, 25","4":"10, 11"}},{"t":"case","label":"Zivotofsky v. Clinton","cite":"566 U.S. 189","y":2012,"id":"2011/10-699","sc":1,"sum":"The Court held that a dispute over passport regulation was not a political issue and is thus liable for judicial review.","sumSrc":"Oyez","by":{"0":"39"}},{"t":"const","label":"Article II, Section 2, Clause 2","clauses":[["treaty","Treaty Clause"],["appointments","Appointments Clause"]],"text":"He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments.","by":{"0":"passim","1":"passim","3":"passim","4":"passim"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"32"}},{"t":"usc","label":"42 U.S.C. § 301-1397mm","url":"https://www.law.cornell.edu/uscode/text/42/301-1397mm","tname":"The Public Health and Welfare","by":{"0":"passim","4":"12"}},{"t":"usc","label":"42 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/42/401","stext":{"head":"§401. Trust Funds","paras":[[0,"(a) Federal Old-Age and Survivors Insurance Trust Fund"],[0,"There is hereby created on the books of the Treasury of the United States a trust fund to be known as the \"Federal Old-Age and Survivors Insurance Trust Fund\". The Federal Old-Age and Survivors Insurance Trust Fund shall consist of the securities held by the Secretary of the Treasury for the Old-Age Reserve Account and the amount standing to the credit of the Old-Age Reserve Account on the books of the Treasury on January 1, 1940, which securities and amount the Secretary of the Treasury is authorized and directed to transfer to the Federal Old-Age and Survivors Insurance Trust Fund, and, in addition, such gifts and bequests as may be made as provided in subsection (i)(1), and such amounts as may be appropriated to, or deposited in, the Federal Old-Age and Survivors Insurance Trust Fund as hereinafter provided. There is hereby appropriated to the Federal Old-Age and Survivors Insurance Trust Fund for the fiscal year ending June 30, 1941, and for each fiscal year thereafter, out of any moneys in the Treasury not otherwise appropriated, amounts equivalent to 100 per centum of—"],[1,"(1) the taxes (including interest, penalties, and additions to the taxes) received under subchapter A of chapter 9 of the Internal Revenue Code of 1939 (and covered into the Treasury) which are deposited into the Treasury by collectors of internal revenue before January 1, 1951; and"],[1,"(2) the taxes certified each month by the Commissioner of Internal Revenue as taxes received under subchapter A of chapter 9 of such Code which are deposited into the Treasury by collectors of internal revenue after December 31, 1950, and before January 1, 1953, with respect to assessments of such taxes made before January 1, 1951; and"],[1,"(3) the taxes imposed by subchapter A of chapter 9 of such Code with respect to wages (as defined in section 1426 of such Code), and by chapter 21 (other than sections 3101(b) and 3111(b)) of the Internal Revenue Code of 1954 with respect to wages (as defined in section 3121 of such Code) reported to the Commissioner of Internal Revenue pursuant to section 1420(c) of the Internal Revenue Code of 1939 after December 31, 1950, or to the Secretary of the Treasury or his delegates pursuant to subtitle F of the Internal Revenue Code of 1954 after December 31, 1954, as determined by the Secretary of the Treasury by applying the applicable rates of tax under such subchapter or chapter 21 (other than sections 3101(b) and 3111(b)) to such wages, which wages shall be certified by the Commissioner of Social Security on the basis of the records of wages established and maintained by such Commissioner in accordance with such reports, less the amounts specified in clause (1) of subsection (b) of this section; and"],[1,"(4) the taxes imposed by subchapter E of chapter 1 of the Internal Revenue Code of 1939, with respect to self-employment income (as defined in section 481 of such Code), and by chapter 2 (other than section 1401(b)) of the Internal Revenue Code of 1954 with respect to self-employment income (as defined in section 1402 of such Code) reported to the Commissioner of Internal Revenue on tax returns under such subchapter or to the Secretary of the Treasury or his delegate on tax returns under subtitle F of such Code, as determined by the Secretary of the Treasury by applying the applicable rate of tax under such subchapter or chapter (other than section 1401(b)) to such self-employment income, which self-employment income shall be certified by the Commissioner of Social Security on the basis of the records of self-employment income established and maintained by the Commissioner of Social Security in accordance with such returns, less the amounts specified in clause (2) of subsection (b) of this section."],[0,"The amounts appropriated by clauses (3) and (4) of this subsection shall be transferred from time to time from the general fund in the Treasury to the Federal Old-Age and Survivors Insurance Trust Fund, and the amounts appropriated by clauses (1) and (2) of subsection (b) shall be transferred from time to time from the general fund in the Treasury to the Federal Disability Insurance Trust Fund, such amounts to be determined on the basis of estimates by the Secretary of the Treasury of the taxes, specified in clauses (3) and (4) of this subsection, paid to or deposited into the Treasury; and proper adjustments shall be made in amounts subsequently transferred to the extent prior estimates were in excess of or were less than the taxes specified in such clauses (3) and (4) of this subsection. All amounts transferred to either Trust Fund under the preceding sentence shall be invested by the Managing Trustee in the same manner and to the same extent as the other assets of such Trust Fund. Notwithstanding the preceding sentence, in any case in which the Secretary of the Treasury determines that the assets of either such Trust Fund would otherwise be inadequate to meet such Fund's obligations for any month, the Secretary of the Treasury shall transfer to such Trust Fund on the first day of such month the amount which would have been transferred to such Fund under this section as in effect on October 1, 1990; and such Trust Fund shall pay interest to the general fund on the amount so transferred on the first day of any month at a rate (calculated on a daily basis, and applied against the difference between the amount so transferred on such first day and the amount which would have been transferred to the Trust Fund up to that day under the procedures in effect on January 1, 1983) equal to the rate earned by the investments of such Fund in the same month under subsection (d)."],[0,"(b) Federal Disability Insurance Trust Fund"],[0,"There is hereby created on the books of the Treasury of the United States a trust fund to be known as the \"Federal Disability Insurance Trust Fund\". The Federal Disability Insurance Trust Fund shall consist of such gifts and bequests as may be made as provided in subsection (i)(1), and such amounts as may be appropriated to, or deposited in, such fund as provided in this section. There is hereby appropriated to the Federal Disability Insurance Trust Fund for the fiscal year ending June 30, 1957, and for each fiscal year thereafter, out of any moneys in the Treasury not otherwise appropriated, amounts equivalent to 100 per centum of—"],[1,"(1)(A) ½ of 1 per centum of the wages (as defined in section 3121 of the Internal Revenue Code of 1954) paid after December 31, 1956, and before January 1, 1966, and reported to the Secretary of the Treasury or his delegate pursuant to subtitle F of the Internal Revenue Code of 1954, (B) 0.70 of 1 per centum of the wages (as so defined) paid after December 31, 1965, and before January 1, 1968, and so reported, (C) 0.95 of 1 per centum of the wages (as so defined) paid after December 31, 1967, and before January 1, 1970, and so reported, (D) 1.10 per centum of the wages (as so defined) paid after December 31, 1969, and before January 1, 1973, and so reported, (E) 1.1 per centum of the wages (as so defined) paid after December 31, 1972, and before January 1, 1974, and so reported, (F) 1.15 per centum of the wages (as so defined) paid after December 31, 1973, and before January 1, 1978, and so reported, (G) 1.55 per centum of the wages (as so defined) paid after December 31, 1977, and before January 1, 1979, and so reported, (H) 1.50 per centum of the wages (as so defined) paid after December 31, 1978, and before January 1, 1980, and so reported, (I) 1.12 per centum of the wages (as so defined) paid after December 31, 1979, and before January 1, 1981, and so reported, (J) 1.30 per centum of the wages (as so defined) paid after December 31, 1980, and before January 1, 1982, and so reported, (K) 1.65 per centum of the wages (as so defined) paid after December 31, 1981, and before January 1, 1983, and so reported, (L) 1.25 per centum of the wages (as so defined) paid after December 31, 1982, and before January 1, 1984, and so reported, (M) 1.00 per centum of the wages (as so defined) paid after December 31, 1983, and before January 1, 1988, and so reported, (N) 1.06 per centum of the wages (as so defined) paid after December 31, 1987, and before January 1, 1990, and so reported, (O) 1.20 per centum of the wages (as so defined) paid after December 31, 1989, and before January 1, 1994, and so reported, (P) 1.88 per centum of the wages (as so defined) paid after December 31, 1993, and before January 1, 1997, and so reported, (Q) 1.70 per centum of the wages (as so defined) paid after December 31, 1996, and before January 1, 2000, and so reported, (R) 1.80 per centum of the wages (as so defined) paid after December 31, 1999, and before January 1, 2016, and so reported, (S) 2.37 per centum of the wages (as so defined) paid after December 31, 2015, and before January 1, 2019, and so reported, and (T) 1.80 per centum of the wages (as so defined) paid after December 31, 2018, and so reported,,1 which wages shall be certified by the Commissioner of Social Security on the basis of the records of wages established and maintained by such Commissioner in accordance with such reports; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/401?type=usc&year=mostrecent&link-type=html"},"head":"§401. Trust Funds","tname":"The Public Health and Welfare","by":{"0":"5, 8","2":"3, 7"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(a)","(b)(1)","(g)","(l)"],"stext":{"head":"§405. Evidence, procedure, and certification for payments","paras":[[0,"(a) Rules and regulations; procedures"],[0,"The Commissioner of Social Security shall have full power and authority to make rules and regulations and to establish procedures, not inconsistent with the provisions of this subchapter, which are necessary or appropriate to carry out such provisions, and shall adopt reasonable and proper rules and regulations to regulate and provide for the nature and extent of the proofs and evidence and the method of taking and furnishing the same in order to establish the right to benefits hereunder."],[0,"(b) Administrative determination of entitlement to benefits; findings of fact; hearings; investigations; evidentiary hearings in reconsiderations of disability benefit terminations; subsequent applications"],[0,"(1) The Commissioner of Social Security is directed to make findings of fact, and decisions as to the rights of any individual applying for a payment under this subchapter. Any such decision by the Commissioner of Social Security which involves a determination of disability and which is in whole or in part unfavorable to such individual shall contain a statement of the case, in understandable language, setting forth a discussion of the evidence, and stating the Commissioner's determination and the reason or reasons upon which it is based. Upon request by any such individual or upon request by a wife, divorced wife, widow, surviving divorced wife, surviving divorced mother, surviving divorced father, husband, divorced husband, widower, surviving divorced husband, child, or parent who makes a showing in writing that his or her rights may be prejudiced by any decision the Commissioner of Social Security has rendered, the Commissioner shall give such applicant and such other individual reasonable notice and opportunity for a hearing with respect to such decision, and, if a hearing is held, shall, on the basis of evidence adduced at the hearing, affirm, modify, or reverse the Commissioner's findings of fact and such decision. Any such request with respect to such a decision must be filed within sixty days after notice of such decision is received by the individual making such request. The Commissioner of Social Security is further authorized, on the Commissioner's own motion, to hold such hearings and to conduct such investigations and other proceedings as the Commissioner may deem necessary or proper for the administration of this subchapter. In the course of any hearing, investigation, or other proceeding, the Commissioner may administer oaths and affirmations, examine witnesses, and receive evidence. Evidence may be received at any hearing before the Commissioner of Social Security even though inadmissible under rules of evidence applicable to court procedure."],[0,"(2) In any case where—"],[1,"(A) an individual is a recipient of disability insurance benefits, or of child's, widow's, or widower's insurance benefits based on disability,"],[1,"(B) the physical or mental impairment on the basis of which such benefits are payable is found to have ceased, not to have existed, or to no longer be disabling, and"],[1,"(C) as a consequence of the finding described in subparagraph (B), such individual is determined by the Commissioner of Social Security not to be entitled to such benefits,"],[0,"any reconsideration of the finding described in subparagraph (B), in connection with a reconsideration by the Commissioner of Social Security (before any hearing under paragraph (1) on the issue of such entitlement) of the Commissioner's determination described in subparagraph (C), shall be made only after opportunity for an evidentiary hearing, with regard to the finding described in subparagraph (B), which is reasonably accessible to such individual. Any reconsideration of a finding described in subparagraph (B) may be made either by the State agency or the Commissioner of Social Security where the finding was originally made by the State agency, and shall be made by the Commissioner of Social Security where the finding was originally made by the Commissioner of Social Security. In the case of a reconsideration by a State agency of a finding described in subparagraph (B) which was originally made by such State agency, the evidentiary hearing shall be held by an adjudicatory unit of the State agency other than the unit that made the finding described in subparagraph (B). In the case of a reconsideration by the Commissioner of Social Security of a finding described in subparagraph (B) which was originally made by the Commissioner of Social Security, the evidentiary hearing shall be held by a person other than the person or persons who made the finding described in subparagraph (B)."],[0,"(3)(A) A failure to timely request review of an initial adverse determination with respect to an application for any benefit under this subchapter or an adverse determination on reconsideration of such an initial determination shall not serve as a basis for denial of a subsequent application for any benefit under this subchapter if the applicant demonstrates that the applicant, or any other individual referred to in paragraph (1), failed to so request such a review acting in good faith reliance upon incorrect, incomplete, or misleading information, relating to the consequences of reapplying for benefits in lieu of seeking review of an adverse determination, provided by any officer or employee of the Social Security Administration or any State agency acting under section 421 of this title."],[0,"(B) In any notice of an adverse determination with respect to which a review may be requested under paragraph (1), the Commissioner of Social Security shall describe in clear and specific language the effect on possible entitlement to benefits under this subchapter of choosing to reapply in lieu of requesting review of the determination."],[0,"(c) Wage records"],[0,"(1) For the purposes of this subsection—"],[1,"(A) The term \"year\" means a calendar year when used with respect to wages and a taxable year when used with respect to self-employment income."],[1,"(B) The term \"time limitation\" means a period of three years, three months, and fifteen days."],[1,"(C) The term \"survivor\" means an individual's spouse, surviving divorced wife, surviving divorced husband, surviving divorced mother, surviving divorced father, child, or parent, who survives such individual."],[1,"(D) The term \"period\" when used with respect to self-employment income means a taxable year and when used with respect to wages means—"],[2,"(i) a quarter if wages were reported or should have been reported on a quarterly basis on tax returns filed with the Secretary of the Treasury or his delegate under section 6011 of the Internal Revenue Code of 1986 or regulations thereunder (or on reports filed by a State under section 418(e) 1 of this title (as in effect prior to December 31, 1986) or regulations thereunder),"],[2,"(ii) a year if wages were reported or should have been reported on a yearly basis on such tax returns or reports, or"],[2,"(iii) the half year beginning January 1 or July 1 in the case of wages which were reported or should have been reported for calendar year 1937."],[0,"(2)(A) On the basis of information obtained by or submitted to the Commissioner of Social Security, and after such verification thereof as the Commissioner deems necessary, the Commissioner of Social Security shall establish and maintain records of the amounts of wages paid to, and the amounts of self-employment income derived by, each individual and of the periods in which such wages were paid and such income was derived and, upon request, shall inform any individual or his survivor, or the legal representative of such individual or his estate, of the amounts of wages and self-employment income of such individual and the periods during which such wages were paid and such income was derived, as shown by such records at the time of such request."],[0,"(B)(i) In carrying out the Commissioner's duties under subparagraph (A) and subparagraph (F), the Commissioner of Social Security shall take affirmative measures to assure that social security account numbers will, to the maximum extent practicable, be assigned to all members of appropriate groups or categories of individuals by assigning such numbers (or ascertaining that such numbers have already been assigned):"],[1,"(I) to aliens at the time of their lawful admission to the United States either for permanent residence or under other authority of law permitting them to engage in employment in the United States and to other aliens at such time as their status is so changed as to make it lawful for them to engage in such employment;"],[1,"(II) to any individual who is an applicant for or recipient of benefits under any program financed in whole or in part from Federal funds including any child on whose behalf such benefits are claimed by another person; and"],[1,"(III) to any other individual when it appears that he could have been but was not assigned an account number under the provisions of subclauses (I) or (II) but only after such investigation as is necessary to establish to the satisfaction of the Commissioner of Social Security, the identity of such individual, the fact that an account number has not already been assigned to such individual, and the fact that such individual is a citizen or a noncitizen who is not, because of his alien status, prohibited from engaging in employment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/405?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§405. Evidence, procedure, and certification for payments","tname":"The Public Health and Welfare","by":{"0":"24, 39, passim, 39","2":"3, 3, 20, 4, 20","4":"13, passim"}},{"t":"usc","label":"42 U.S.C. § 423","url":"https://www.law.cornell.edu/uscode/text/42/423","subs":["(d)(5)(B)"],"by":{"0":"40, 41"}},{"t":"usc","label":"42 U.S.C. § 1381-1383f","url":"https://www.law.cornell.edu/uscode/text/42/1381-1383f","by":{"0":"5, 6, 8"}},{"t":"usc","label":"42 U.S.C. § 1320a-8","url":"https://www.law.cornell.edu/uscode/text/42/1320a-8","subs":["(a)","(b)(2)","(c)","(d)(1)"],"stext":{"head":"§1320a–8. Civil monetary penalties and assessments for subchapters II, VIII and XVI","paras":[[0,"(a) False statements or representations of material fact; proceedings to exclude; wrongful conversions by representative payees"],[0,"(1) Any person (including an organization, agency, or other entity) who—"],[1,"(A) makes, or causes to be made, a statement or representation of a material fact, for use in determining any initial or continuing right to or the amount of monthly insurance benefits under subchapter II or benefits or payments under subchapter VIII or XVI, that the person knows or should know is false or misleading,"],[1,"(B) makes such a statement or representation for such use with knowing disregard for the truth, or"],[1,"(C) omits from a statement or representation for such use, or otherwise withholds disclosure of, a fact which the person knows or should know is material to the determination of any initial or continuing right to or the amount of monthly insurance benefits under subchapter II or benefits or payments under subchapter VIII or XVI, if the person knows, or should know, that the statement or representation with such omission is false or misleading or that the withholding of such disclosure is misleading,"],[0,"shall be subject to, in addition to any other penalties that may be prescribed by law, a civil money penalty of not more than $5,000 for each such statement or representation or each receipt of such benefits or payments while withholding disclosure of such fact, except that in the case of such a person who receives a fee or other income for services performed in connection with any such determination (including a claimant representative, translator, or current or former employee of the Social Security Administration) or who is a physician or other health care provider who submits, or causes the submission of, medical or other evidence in connection with any such determination, the amount of such penalty shall be not more than $7,500. Such person also shall be subject to an assessment, in lieu of damages sustained by the United States because of such statement or representation or because of such withholding of disclosure of a material fact, of not more than twice the amount of benefits or payments paid as a result of such a statement or representation or such a withholding of disclosure. In addition, the Commissioner of Social Security may make a determination in the same proceeding to recommend that the Secretary exclude, as provided in section 1320a–7 of this title, such a person who is a medical provider or physician from participation in the programs under subchapter XVIII."],[0,"(2) For purposes of this section, a material fact is one which the Commissioner of Social Security may consider in evaluating whether an applicant is entitled to benefits under subchapter II or subchapter VIII, or eligible for benefits or payments under subchapter XVI."],[0,"(3) Any person (including an organization, agency, or other entity) who, having received, while acting in the capacity of a representative payee pursuant to section 405(j), 1007, or 1383(a)(2) of this title, a payment under subchapter II, VIII, or XVI for the use and benefit of another individual, converts such payment, or any part thereof, to a use that such person knows or should know is other than for the use and benefit of such other individual shall be subject to, in addition to any other penalties that may be prescribed by law, a civil money penalty of not more than $5,000 for each such conversion. Such person shall also be subject to an assessment, in lieu of damages sustained by the United States resulting from the conversion, of not more than twice the amount of any payments so converted."],[0,"(b) Initiation of proceedings; hearing; sanctions"],[0,"(1) The Commissioner of Social Security may initiate a proceeding to determine whether to impose a civil money penalty or assessment, or whether to recommend exclusion under subsection (a) only as authorized by the Attorney General pursuant to procedures agreed upon by the Commissioner of Social Security and the Attorney General. The Commissioner of Social Security may not initiate an action under this section with respect to any violation described in subsection (a) later than 6 years after the date the violation was committed. The Commissioner of Social Security may initiate an action under this section by serving notice of the action in any manner authorized by Rule 4 of the Federal Rules of Civil Procedure."],[0,"(2) The Commissioner of Social Security shall not make a determination adverse to any person under this section until the person has been given written notice and an opportunity for the determination to be made on the record after a hearing at which the person is entitled to be represented by counsel, to present witnesses, and to cross-examine witnesses against the person."],[0,"(3) In a proceeding under this section which—"],[1,"(A) is against a person who has been convicted (whether upon a verdict after trial or upon a plea of guilty or nolo contendere) of a Federal or State crime; and"],[1,"(B) involves the same transaction as in the criminal action;"],[0,"the person is estopped from denying the essential elements of the criminal offense."],[0,"(4) The official conducting a hearing under this section may sanction a person, including any party or attorney, for failing to comply with an order or procedure, for failing to defend an action, or for such other misconduct as would interfere with the speedy, orderly, or fair conduct of the hearing. Such sanction shall reasonably relate to the severity and nature of the failure or misconduct. Such sanction may include—"],[1,"(A) in the case of refusal to provide or permit discovery, drawing negative factual inference or treating such refusal as an admission by deeming the matter, or certain facts, to be established;"],[1,"(B) prohibiting a party from introducing certain evidence or otherwise supporting a particular claim or defense;"],[1,"(C) striking pleadings, in whole or in part;"],[1,"(D) staying the proceedings;"],[1,"(E) dismissal of the action;"],[1,"(F) entering a default judgment;"],[1,"(G) ordering the party or attorney to pay attorneys' fees and other costs caused by the failure or misconduct; and"],[1,"(H) refusing to consider any motion or other action which is not filed in a timely manner."],[0,"(c) Amount or scope of penalties, assessments, or exclusions"],[0,"In determining pursuant to subsection (a) the amount or scope of any penalty or assessment, or whether to recommend an exclusion, the Commissioner of Social Security shall take into account—"],[1,"(1) the nature of the statements, representations, or actions referred to in subsection (a) and the circumstances under which they occurred;"],[1,"(2) the degree of culpability, history of prior offenses, and financial condition of the person committing the offense; and"],[1,"(3) such other matters as justice may require."],[0,"(d) Judicial review"],[0,"(1) Any person adversely affected by a determination of the Commissioner of Social Security under this section may obtain a review of such determination in the United States Court of Appeals for the circuit in which the person resides, or in which the statement or representation referred to in subsection (a) was made, by filing in such court (within 60 days following the date the person is notified of the Commissioner's determination) a written petition requesting that the determination be modified or set aside. A copy of the petition shall be forthwith transmitted by the clerk of the court to the Commissioner of Social Security, and thereupon the Commissioner of Social Security shall file in the court the record in the proceeding as provided in section 2112 of title 28. Upon such filing, the court shall have jurisdiction of the proceeding and of the question determined therein, and shall have the power to make and enter upon the pleadings, testimony, and proceedings set forth in such record a decree affirming, modifying, remanding for further consideration, or setting aside, in whole or in part, the determination of the Commissioner of Social Security and enforcing the same to the extent that such order is affirmed or modified. No objection that has not been urged before the Commissioner of Social Security shall be considered by the court, unless the failure or neglect to urge such objection shall be excused because of extraordinary circumstances."],[0,"(2) The findings of the Commissioner of Social Security with respect to questions of fact, if supported by substantial evidence on the record considered as a whole, shall be conclusive in the review described in paragraph (1). If any party shall apply to the court for leave to adduce additional evidence and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the hearing before the Commissioner of Social Security, the court may order such additional evidence to be taken before the Commissioner of Social Security and to be made a part of the record. The Commissioner of Social Security may modify such findings as to the facts, or make new findings, by reason of additional evidence so taken and filed, and the Commissioner of Social Security shall file with the court such modified or new findings, which findings with respect to questions of fact, if supported by substantial evidence on the record considered as a whole shall be conclusive, and the Commissioner's recommendations, if any, for the modification or setting aside of the Commissioner's original order."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1320a-8?type=usc&year=mostrecent&link-type=html"},"head":"§1320a–8. Civil monetary penalties and assessments for subchapters II, VIII and XVI","tname":"The Public Health and Welfare","by":{"0":"23, 23, 23, 23","4":"13"}},{"t":"usc","label":"5 U.S.C. § 1104","url":"https://www.law.cornell.edu/uscode/text/5/1104","subs":["(a)(2)"],"by":{"0":"9"}},{"t":"usc","label":"5 U.S.C. § 2102","url":"https://www.law.cornell.edu/uscode/text/5/2102","subs":["(a)"],"by":{"0":"9"}},{"t":"usc","label":"5 U.S.C. § 3304","url":"https://www.law.cornell.edu/uscode/text/5/3304","subs":["(a)(1)"],"by":{"0":"9"}},{"t":"usc","label":"5 U.S.C. § 7123","url":"https://www.law.cornell.edu/uscode/text/5/7123","subs":["(c)"],"stext":{"head":"§7123. Judicial review; enforcement","paras":[[0,"(a) Any person aggrieved by any final order of the Authority other than an order under—"],[1,"(1) section 7122 of this title (involving an award by an arbitrator), unless the order involves an unfair labor practice under section 7118 of this title, or"],[1,"(2) section 7112 of this title (involving an appropriate unit determination),"],[0,"may, during the 60-day period beginning on the date on which the order was issued, institute an action for judicial review of the Authority's order in the United States court of appeals in the circuit in which the person resides or transacts business or in the United States Court of Appeals for the District of Columbia."],[0,"(b) The Authority may petition any appropriate United States court of appeals for the enforcement of any order of the Authority and for appropriate temporary relief or restraining order."],[0,"(c) Upon the filing of a petition under subsection (a) of this section for judicial review or under subsection (b) of this section for enforcement, the Authority shall file in the court the record in the proceedings, as provided in section 2112 of title 28. Upon the filing of the petition, the court shall cause notice thereof to be served to the parties involved, and thereupon shall have jurisdiction of the proceeding and of the question determined therein and may grant any temporary relief (including a temporary restraining order) it considers just and proper, and may make and enter a decree affirming and enforcing, modifying and enforcing as so modified, or setting aside in whole or in part the order of the Authority. The filing of a petition under subsection (a) or (b) of this section shall not operate as a stay of the Authority's order unless the court specifically orders the stay. Review of the Authority's order shall be on the record in accordance with section 706 of this title. No objection that has not been urged before the Authority, or its designee, shall be considered by the court, unless the failure or neglect to urge the objection is excused because of extraordinary circumstances. The findings of the Authority with respect to questions of fact, if supported by substantial evidence on the record considered as a whole, shall be conclusive. If any person applies to the court for leave to adduce additional evidence and shows to the satisfaction of the court that the additional evidence is material and that there were reasonable grounds for the failure to adduce the evidence in the hearing before the Authority, or its designee, the court may order the additional evidence to be taken before the Authority, or its designee, and to be made a part of the record. The Authority may modify its findings as to the facts, or make new findings by reason of additional evidence so taken and filed. The Authority shall file its modified or new findings, which, with respect to questions of fact, if supported by substantial evidence on the record considered as a whole, shall be conclusive. The Authority shall file its recommendations, if any, for the modification or setting aside of its original order. Upon the filing of the record with the court, the jurisdiction of the court shall be exclusive and its judgment and decree shall be final, except that the judgment and decree shall be subject to review by the Supreme Court of the United States upon writ of certiorari or certification as provided in section 1254 of title 28."],[0,"(d) The Authority may, upon issuance of a complaint as provided in section 7118 of this title charging that any person has engaged in or is engaging in an unfair labor practice, petition any United States district court within any district in which the unfair labor practice in question is alleged to have occurred or in which such person resides or transacts business for appropriate temporary relief (including a restraining order). Upon the filing of the petition, the court shall cause notice thereof to be served upon the person, and thereupon shall have jurisdiction to grant any temporary relief (including a temporary restraining order) it considers just and proper. A court shall not grant any temporary relief under this section if it would interfere with the ability of the agency to carry out its essential functions or if the Authority fails to establish probable cause that an unfair labor practice is being committed."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7123?type=usc&year=mostrecent&link-type=html"},"head":"§7123. Judicial review; enforcement","tname":"Government Organization and Employees","by":{"0":"22","1":"19"}},{"t":"usc","label":"15 U.S.C. § 77i","url":"https://www.law.cornell.edu/uscode/text/15/77i","subs":["(a)"],"by":{"0":"22"}},{"t":"usc","label":"15 U.S.C. § 687a","url":"https://www.law.cornell.edu/uscode/text/15/687a","subs":["(e)"],"by":{"0":"23"}},{"t":"usc","label":"15 U.S.C. § 717r","url":"https://www.law.cornell.edu/uscode/text/15/717r","subs":["(b)"],"by":{"0":"23"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"2"}},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","subs":["(e)"],"stext":{"head":"§160. Prevention of unfair labor practices","paras":[[0,"(a) Powers of Board generally"],[0,"The Board is empowered, as hereinafter provided, to prevent any person from engaging in any unfair labor practice (listed in section 158 of this title) affecting commerce. This power shall not be affected by any other means of adjustment or prevention that has been or may be established by agreement, law, or otherwise: Provided, That the Board is empowered by agreement with any agency of any State or Territory to cede to such agency jurisdiction over any cases in any industry (other than mining, manufacturing, communications, and transportation except where predominantly local in character) even though such cases may involve labor disputes affecting commerce, unless the provision of the State or Territorial statute applicable to the determination of such cases by such agency is inconsistent with the corresponding provision of this subchapter or has received a construction inconsistent therewith."],[0,"(b) Complaint and notice of hearing; answer; court rules of evidence inapplicable"],[0,"Whenever it is charged that any person has engaged in or is engaging in any such unfair labor practice, the Board, or any agent or agency designated by the Board for such purposes, shall have power to issue and cause to be served upon such person a complaint stating the charges in that respect, and containing a notice of hearing before the Board or a member thereof, or before a designated agent or agency, at a place therein fixed, not less than five days after the serving of said complaint: Provided, That no complaint shall issue based upon any unfair labor practice occurring more than six months prior to the filing of the charge with the Board and the service of a copy thereof upon the person against whom such charge is made, unless the person aggrieved thereby was prevented from filing such charge by reason of service in the armed forces, in which event the six-month period shall be computed from the day of his discharge. Any such complaint may be amended by the member, agent, or agency conducting the hearing or the Board in its discretion at any time prior to the issuance of an order based thereon. The person so complained of shall have the right to file an answer to the original or amended complaint and to appear in person or otherwise and give testimony at the place and time fixed in the complaint. In the discretion of the member, agent, or agency conducting the hearing or the Board, any other person may be allowed to intervene in the said proceeding and to present testimony. Any such proceeding shall, so far as practicable, be conducted in accordance with the rules of evidence applicable in the district courts of the United States under the rules of civil procedure for the district courts of the United States, adopted by the Supreme Court of the United States pursuant to section 2072 of title 28."],[0,"(c) Reduction of testimony to writing; findings and orders of Board"],[0,"The testimony taken by such member, agent, or agency or the Board shall be reduced to writing and filed with the Board. Thereafter, in its discretion, the Board upon notice may take further testimony or hear argument. If upon the preponderance of the testimony taken the Board shall be of the opinion that any person named in the complaint has engaged in or is engaging in any such unfair labor practice, then the Board shall state its findings of fact and shall issue and cause to be served on such person an order requiring such person to cease and desist from such unfair labor practice, and to take such affirmative action including reinstatement of employees with or without back pay, as will effectuate the policies of this subchapter: Provided, That where an order directs reinstatement of an employee, back pay may be required of the employer or labor organization, as the case may be, responsible for the discrimination suffered by him: And provided further, That in determining whether a complaint shall issue alleging a violation of subsection (a)(1) or (a)(2) of section 158 of this title, and in deciding such cases, the same regulations and rules of decision shall apply irrespective of whether or not the labor organization affected is affiliated with a labor organization national or international in scope. Such order may further require such person to make reports from time to time showing the extent to which it has complied with the order. If upon the preponderance of the testimony taken the Board shall not be of the opinion that the person named in the complaint has engaged in or is engaging in any such unfair labor practice, then the Board shall state its findings of fact and shall issue an order dismissing the said complaint. No order of the Board shall require the reinstatement of any individual as an employee who has been suspended or discharged, or the payment to him of any back pay, if such individual was suspended or discharged for cause. In case the evidence is presented before a member of the Board, or before an administrative law judge or judges thereof, such member, or such judge or judges as the case may be, shall issue and cause to be served on the parties to the proceeding a proposed report, together with a recommended order, which shall be filed with the Board, and if no exceptions are filed within twenty days after service thereof upon such parties, or within such further period as the Board may authorize, such recommended order shall become the order of the Board and become effective as therein prescribed."],[0,"(d) Modification of findings or orders prior to filing record in court"],[0,"Until the record in a case shall have been filed in a court, as hereinafter provided, the Board may at any time upon reasonable notice and in such manner as it shall deem proper, modify or set aside, in whole or in part, any finding or order made or issued by it."],[0,"(e) Petition to court for enforcement of order; proceedings; review of judgment"],[0,"The Board shall have power to petition any court of appeals of the United States, or if all the courts of appeals to which application may be made are in vacation, any district court of the United States, within any circuit or district, respectively, wherein the unfair labor practice in question occurred or wherein such person resides or transacts business, for the enforcement of such order and for appropriate temporary relief or restraining order, and shall file in the court the record in the proceedings, as provided in section 2112 of title 28. Upon the filing of such petition, the court shall cause notice thereof to be served upon such person, and thereupon shall have jurisdiction of the proceeding and of the question determined therein, and shall have power to grant such temporary relief or restraining order as it deems just and proper, and to make and enter a decree enforcing, modifying and enforcing as so modified, or setting aside in whole or in part the order of the Board. No objection that has not been urged before the Board, its member, agent, or agency, shall be considered by the court, unless the failure or neglect to urge such objection shall be excused because of extraordinary circumstances. The findings of the Board with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall be conclusive. If either party shall apply to the court for leave to adduce additional evidence and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the hearing before the Board, its member, agent, or agency, the court may order such additional evidence to be taken before the Board, its member, agent, or agency, and to be made a part of the record. The Board may modify its findings as to the facts, or make new findings by reason of additional evidence so taken and filed, and it shall file such modified or new findings, which findings with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall be conclusive, and shall file its recommendations, if any, for the modification or setting aside of its original order. Upon the filing of the record with it the jurisdiction of the court shall be exclusive and its judgment and decree shall be final, except that the same shall be subject to review by the appropriate United States court of appeals if application was made to the district court as hereinabove provided, and by the Supreme Court of the United States upon writ of certiorari or certification as provided in section 1254 of title 28."],[0,"(f) Review of final order of Board on petition to court"],[0,"Any person aggrieved by a final order of the Board granting or denying in whole or in part the relief sought may obtain a review of such order in any United States court of appeals in the circuit wherein the unfair labor practice in question was alleged to have been engaged in or wherein such person resides or transacts business, or in the United States Court of Appeals for the District of Columbia, by filing in such a court a written petition praying that the order of the Board be modified or set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Board, and thereupon the aggrieved party shall file in the court the record in the proceeding, certified by the Board, as provided in section 2112 of title 28. Upon the filing of such petition, the court shall proceed in the same manner as in the case of an application by the Board under subsection (e), and shall have the same jurisdiction to grant to the Board such temporary relief or restraining order as it deems just and proper, and in like manner to make and enter a decree enforcing, modifying, and enforcing as so modified, or setting aside in whole or in part the order of the Board; the findings of the Board with respect to questions of fact if supported by substantial evidence on the record considered as a whole shall in like manner be conclusive."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/160?type=usc&year=mostrecent&link-type=html"},"head":"§160. Prevention of unfair labor practices","tname":"Labor","by":{"0":"19, 23","1":"19"}},{"t":"usc","label":"29 U.S.C. § 210","url":"https://www.law.cornell.edu/uscode/text/29/210","subs":["(a)"],"by":{"0":"23"}},{"t":"usc","label":"30 U.S.C. § 816","url":"https://www.law.cornell.edu/uscode/text/30/816","subs":["(a)(1)"],"stext":{"head":"§816. Judicial review of Commission orders","paras":[[0,"(a) Petition by person adversely affected or aggrieved; temporary relief"],[0,"(1) Any person adversely affected or aggrieved by an order of the Commission issued under this chapter may obtain a review of such order in any United States court of appeals for the circuit in which the violation is alleged to have occurred or in the United States Court of Appeals for the District of Columbia Circuit, by filing in such court within 30 days following the issuance of such order a written petition praying that the order be modified or set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court to the Commission and to the other parties, and thereupon the Commission shall file in the court the record in the proceeding as provided in section 2112 of title 28. Upon such filing, the court shall have exclusive jurisdiction of the proceeding and of the questions determined therein, and shall have the power to make and enter upon the pleadings, testimony, and proceedings set forth in such record a decree affirming, modifying, or setting aside, in whole or in part, the order of the Commission and enforcing the same to the extent that such order is affirmed or modified. No objection that has not been urged before the Commission shall be considered by the court, unless the failure or neglect to urge such objection shall be excused because of extraordinary circumstances. The findings of the Commission with respect to questions of fact, if supported by substantial evidence on the record considered as a whole, shall be conclusive. If any party shall apply to the court for leave to adduce additional evidence and shall show to the satisfaction of the court that such additional evidence is material and that there were reasonable grounds for the failure to adduce such evidence in the hearing before the Commission, the court may order such additional evidence to be taken before the Commission and to be made a part of the record. The Commission may modify its findings as to the facts, or make new findings, by reason of additional evidence so taken and filed, and it shall file such modified or new findings, which findings with respect to questions of fact, if supported by substantial evidence on the record considered as a whole, shall be conclusive. The Commission may modify or set aside its original order by reason of such modified or new findings of fact. Upon the filing of the record after such remand proceedings, the jurisdiction of the court shall be exclusive and its judgment and degree shall be final, except that the same shall be subject to review by the Supreme Court of the United States, as provided in section 1254 of title 28."],[0,"(2) In the case of a proceeding to review any order or decision issued by the Commission under this chapter, except an order or decision pertaining to an order issued under section 817(a) of this title or an order or decision pertaining to a citation issued under section 814(a) or (f) of this title, the court may, under such conditions as it may prescribe, grant such temporary relief as it deems appropriate pending final determination of the proceeding, if—"],[1,"(A) all parties to the proceeding have been notified and given an opportunity to be heard on a request for temporary relief;"],[1,"(B) the person requesting such relief shows that there is a substantial likelihood that he will prevail on the merits of the final determination of the proceeding; and"],[1,"(C) such relief will not adversely affect the health and safety of miners in the coal or other mine."],[0,"(3) In the case of a proceeding to review any order or decision issued by the Panel under this chapter, the court may, under such conditions as it may prescribe, grant such temporary relief as it deems appropriate pending final determination of the proceeding, if—"],[1,"(A) all parties to the proceeding have been notified and given an opportunity to be heard on a request for temporary relief; and"],[1,"(B) the person requesting such relief shows that there is a substantial likelihood that he will prevail on the merits of the final determination of the proceeding."],[0,"(b) Petition by Secretary for review or enforcement of final Commission orders"],[0,"The Secretary may also obtain review or enforcement of any final order of the Commission by filing a petition for such relief in the United States court of appeals for the circuit in which the alleged violation occurred or in the Court of Appeals for the District of Columbia Circuit, and the provisions of subsection (a) shall govern such proceedings to the extent applicable. If no petition for review, as provided in subsection (a), is filed within 30 days after issuance of the Commission's order, the Commission's findings of fact and order shall be conclusive in connection with any petition for enforcement which is filed by the Secretary after the expiration of such 30-day period. In any such case, as well as in the case of a noncontested citation or notification by the Secretary which has become a final order of the Commission under subsection (a) or (b) of section 815 of this title, the clerk of the court, unless otherwise ordered by the court, shall forthwith enter a decree enforcing the order and shall transmit a copy of such decree to the Secretary and the operator named in the petition. In any contempt proceeding brought to enforce a decree of a court of appeals entered pursuant to this subsection or subsection (a), the court of appeals may assess the penalties provided in section 820 of this title, in addition to invoking any other available remedies."],[0,"(c) Stay of order or decision of Commission or Panel"],[0,"The commencement of a proceeding under this section shall not, unless specifically ordered by the court, operate as a stay of the order or decision of the Commission or the Panel."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/30/816?type=usc&year=mostrecent&link-type=html"},"head":"§816. Judicial review of Commission orders","tname":"Mineral Lands and Mining","by":{"0":"23","1":"19","2":"11"}},{"t":"usc","label":"43 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/43/1349","subs":["(c)(5)"],"stext":{"head":"§1349. Citizens suits, jurisdiction and judicial review","paras":[[0,"(a) Persons who may bring actions; persons against whom action may be brought; time of action; intervention by Attorney General; costs and fees; security"],[0,"(1) Except as provided in this section, any person having a valid legal interest which is or may be adversely affected may commence a civil action on his own behalf to compel compliance with this subchapter against any person, including the United States, and any other government instrumentality or agency (to the extent permitted by the eleventh amendment to the Constitution) for any alleged violation of any provision of this subchapter or any regulation promulgated under this subchapter, or of the terms of any permit or lease issued by the Secretary under this subchapter."],[0,"(2) Except as provided in paragraph (3) of this subsection, no action may be commenced under subsection (a)(1) of this section—"],[1,"(A) prior to sixty days after the plaintiff has given notice of the alleged violation, in writing under oath, to the Secretary and any other appropriate Federal official, to the State in which the violation allegedly occurred or is occurring, and to any alleged violator; or"],[1,"(B) if the Attorney General has commenced and is diligently prosecuting a civil action in a court of the United States or a State with respect to such matter, but in any such action in a court of the United States any person having a legal interest which is or may be adversely affected may intervene as a matter of right."],[0,"(3) An action may be brought under this subsection immediately after notification of the alleged violation in any case in which the alleged violation constitutes an imminent threat to the public health or safety or would immediately affect a legal interest of the plaintiff."],[0,"(4) In any action commenced pursuant to this section, the Attorney General, upon the request of the Secretary or any other appropriate Federal official, may intervene as a matter of right."],[0,"(5) A court, in issuing any final order in any action brought pursuant to subsection (a)(1) or subsection (c) of this section, may award costs of litigation, including reasonable attorney and expert witness fees, to any party, whenever such court determines such award is appropriate. The court may, if a temporary restraining order or preliminary injunction is sought, require the filing of a bond or equivalent security in a sufficient amount to compensate for any loss or damage suffered, in accordance with the Federal Rules of Civil Procedure."],[0,"(6) Except as provided in subsection (c) of this section, all suits challenging actions or decisions allegedly in violation of, or seeking enforcement of, the provisions of this subchapter, or any regulation promulgated under this subchapter, or the terms of any permit or lease issued by the Secretary under this subchapter, shall be undertaken in accordance with the procedures described in this subsection. Nothing in this section shall restrict any right which any person or class of persons may have under any other Act or common law to seek appropriate relief."],[0,"(b) Jurisdiction and venue of actions"],[0,"(1) Except as provided in subsection (c) of this section, the district courts of the United States shall have jurisdiction of cases and controversies arising out of, or in connection with (A) any operation conducted on the outer Continental Shelf which involves exploration, development, or production of the minerals, of the subsoil and seabed of the outer Continental Shelf, or which involves rights to such minerals, or (B) the cancellation, suspension, or termination of a lease or permit under this subchapter. Proceedings with respect to any such case or controversy may be instituted in the judicial district in which any defendant resides or may be found, or in the judicial district of the State nearest the place the cause of action arose."],[0,"(2) Any resident of the United States who is injured in any manner through the failure of any operator to comply with any rule, regulation, order, or permit issued pursuant to this subchapter may bring an action for damages (including reasonable attorney and expert witness fees) only in the judicial district having jurisdiction under paragraph (1) of this subsection."],[0,"(c) Review of Secretary's approval of leasing program; review of approval, modification or disapproval of exploration or production plan; persons who may seek review; scope of review; certiorari to Supreme Court"],[0,"(1) Any action of the Secretary to approve a leasing program pursuant to section 1344 of this title shall be subject to judicial review only in the United States Court of Appeal 1 for the District of Columbia."],[0,"(2) Any action of the Secretary to approve, require modification of, or disapprove any exploration plan or any development and production plan under this subchapter shall be subject to judicial review only in a United States court of appeals for a circuit in which an affected State is located."],[0,"(3) The judicial review specified in paragraphs (1) and (2) of this subsection shall be available only to a person who (A) participated in the administrative proceedings related to the actions specified in such paragraphs, (B) is adversely affected or aggrieved by such action, (C) files a petition for review of the Secretary's action within sixty days after the date of such action, and (D) promptly transmits copies of the petition to the Secretary and to the Attorney General."],[0,"(4) Any action of the Secretary specified in paragraph (1) or (2) shall only be subject to review pursuant to the provisions of this subsection, and shall be specifically excluded from citizen suits which are permitted pursuant to subsection (a) of this section."],[0,"(5) The Secretary shall file in the appropriate court the record of any public hearings required by this subchapter and any additional information upon which the Secretary based his decision, as required by section 2112 of title 28. Specific objections to the action of the Secretary shall be considered by the court only if the issues upon which such objections are based have been submitted to the Secretary during the administrative proceedings related to the actions involved."],[0,"(6) The court of appeals conducting a proceeding pursuant to this subsection shall consider the matter under review solely on the record made before the Secretary. The findings of the Secretary, if supported by substantial evidence on the record considered as a whole, shall be conclusive. The court may affirm, vacate, or modify any order or decision or may remand the proceedings to the Secretary for such further action as it may direct."],[0,"(7) Upon the filing of the record with the court, pursuant to paragraph (5), the jurisdiction of the court shall be exclusive and its judgment shall be final, except that such judgment shall be subject to review by the Supreme Court of the United States upon writ of certiorari."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/43/1349?type=usc&year=mostrecent&link-type=html"},"head":"§1349. Citizens suits, jurisdiction and judicial review","tname":"Public Lands","by":{"0":"23","1":"19"}},{"t":"usc","label":"47 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/47/405","subs":["(a)"],"stext":{"head":"§405. Petition for reconsideration; procedure; disposition; time of filing; additional evidence; time for disposition of petition for reconsideration of order concluding hearing or investigation; appeal of order","paras":[[0,"(a) After an order, decision, report, or action has been made or taken in any proceeding by the Commission, or by any designated authority within the Commission pursuant to a delegation under section 155(c)(1) of this title, any party thereto, or any other person aggrieved or whose interests are adversely affected thereby, may petition for reconsideration only to the authority making or taking the order, decision, report, or action; and it shall be lawful for such authority, whether it be the Commission or other authority designated under section 155(c)(1) of this title, in its discretion, to grant such a reconsideration if sufficient reason therefor be made to appear. A petition for reconsideration must be filed within thirty days from the date upon which public notice is given of the order, decision, report, or action complained of. No such application shall excuse any person from complying with or obeying any order, decision, report, or action of the Commission, or operate in any manner to stay or postpone the enforcement thereof, without the special order of the Commission. The filing of a petition for reconsideration shall not be a condition precedent to judicial review of any such order, decision, report, or action, except where the party seeking such review (1) was not a party to the proceedings resulting in such order, decision, report, or action, or (2) relies on questions of fact or law upon which the Commission, or designated authority within the Commission, has been afforded no opportunity to pass. The Commission, or designated authority within the Commission, shall enter an order, with a concise statement of the reasons therefor, denying a petition for reconsideration or granting such petition, in whole or in part, and ordering such further proceedings as may be appropriate: Provided, That in any case where such petition relates to an instrument of authorization granted without a hearing, the Commission, or designated authority within the Commission, shall take such action within ninety days of the filing of such petition. Reconsiderations shall be governed by such general rules as the Commission may establish, except that no evidence other than newly discovered evidence, evidence which has become available only since the original taking of evidence, or evidence which the Commission or designated authority within the Commission believes should have been taken in the original proceeding shall be taken on any reconsideration. The time within which a petition for review must be filed in a proceeding to which section 402(a) of this title applies, or within which an appeal must be taken under section 402(b) of this title in any case, shall be computed from the date upon which the Commission gives public notice of the order, decision, report, or action complained of."],[0,"(b)(1) Within 90 days after receiving a petition for reconsideration of an order concluding a hearing under section 204(a) of this title or concluding an investigation under section 208(b) of this title, the Commission shall issue an order granting or denying such petition."],[0,"(2) Any order issued under paragraph (1) shall be a final order and may be appealed under section 402(a) of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/405?type=usc&year=mostrecent&link-type=html"},"head":"§405. Petition for reconsideration; procedure; disposition; time of filing; additional evidence; time for disposition of petition for reconsideration of order concluding hearing or investigation; appeal of order","tname":"Telecommunications","by":{"0":"23","1":"19"}},{"t":"usc","label":"49 U.S.C. § 1153","url":"https://www.law.cornell.edu/uscode/text/49/1153","subs":["(b)(4)"],"stext":{"head":"§1153. Judicial review","paras":[[0,"(a) General.—The appropriate court of appeals of the United States or the United States Court of Appeals for the District of Columbia Circuit may review a final order of the National Transportation Safety Board under this chapter. A person disclosing a substantial interest in the order may apply for review by filing a petition not later than 60 days after the order of the Board is issued."],[0,"(b) Persons Seeking Judicial Review of Aviation Matters.—(1) A person disclosing a substantial interest in an order related to an aviation matter issued by the Board under this chapter may apply for review of the order by filing a petition for review in the United States Court of Appeals for the District of Columbia Circuit or in the court of appeals of the United States for the circuit in which the person resides or has its principal place of business. The petition must be filed not later than 60 days after the order is issued. The court may allow the petition to be filed after the 60 days only if there was a reasonable ground for not filing within that 60-day period."],[0,"(2) When a petition is filed under paragraph (1) of this subsection, the clerk of the court immediately shall send a copy of the petition to the Board. The Board shall file with the court a record of the proceeding in which the order was issued."],[0,"(3) When the petition is sent to the Board, the court has exclusive jurisdiction to affirm, amend, modify, or set aside any part of the order and may order the Board to conduct further proceedings. After reasonable notice to the Board, the court may grant interim relief by staying the order or taking other appropriate action when cause for its action exists. Findings of fact by the Board, if supported by substantial evidence, are conclusive."],[0,"(4) In reviewing an order under this subsection, the court may consider an objection to an order of the Board only if the objection was made in the proceeding conducted by the Board or if there was a reasonable ground for not making the objection in the proceeding."],[0,"(5) A decision by a court under this subsection may be reviewed only by the Supreme Court under section 1254 of title 28."],[0,"(c) Administrator Seeking Judicial Review of Aviation Matters.—When the Administrator of the Federal Aviation Administration decides that an order of the Board under section 44703(d), 44709, or 46301(d)(5) of this title will have a significant adverse impact on carrying out this chapter related to an aviation matter, the Administrator may obtain judicial review of the order under section 46110 of this title. The Administrator shall be made a party to the judicial review proceedings. Findings of fact of the Board are conclusive if supported by substantial evidence."],[0,"(d) Commandant Seeking Judicial Review of Maritime Matters.—If the Commandant of the Coast Guard decides that an order of the Board issued pursuant to a review of a Coast Guard action under section 1133 of this title will have an adverse impact on maritime safety or security, the Commandant may obtain judicial review of the order under subsection (a). The Commandant, in the official capacity of the Commandant, shall be a party to the judicial review proceedings."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/49/1153?type=usc&year=mostrecent&link-type=html"},"head":"§1153. Judicial review","tname":"Transportation","by":{"0":"23","1":"19"}},{"t":"reg","label":"5 C.F.R. § 930.201","url":"https://www.ecfr.gov/current/title-5/section-930.201","subs":["(b)"],"by":{"0":"9"}},{"t":"reg","label":"5 C.F.R. § 930.204","url":"https://www.ecfr.gov/current/title-5/section-930.204","subs":["(a)"],"by":{"0":"9"}},{"t":"reg","label":"20 C.F.R. § 404.900","url":"https://www.ecfr.gov/current/title-20/section-404.900","subs":["(a)(6)","(b)"],"by":{"0":"6, 39, 6, 7, 24, 25","4":"7"}},{"t":"reg","label":"20 C.F.R. § 404.933","url":"https://www.ecfr.gov/current/title-20/section-404.933","subs":["(a)"],"by":{"0":"7, 27"}},{"t":"reg","label":"20 C.F.R. § 404.938","url":"https://www.ecfr.gov/current/title-20/section-404.938","subs":["(b)(1)"],"by":{"0":"26"}},{"t":"reg","label":"20 C.F.R. § 404.939","url":"https://www.ecfr.gov/current/title-20/section-404.939","by":{"0":"26, 28, 29","4":"8"}},{"t":"reg","label":"20 C.F.R. § 404.944","url":"https://www.ecfr.gov/current/title-20/section-404.944","by":{"0":"7, 26","4":"7"}},{"t":"reg","label":"20 C.F.R. § 404.946","url":"https://www.ecfr.gov/current/title-20/section-404.946","subs":["(a)"],"by":{"0":"7, 26, 26"}},{"t":"reg","label":"20 C.F.R. § 404.949","url":"https://www.ecfr.gov/current/title-20/section-404.949","by":{"0":"7, 26"}},{"t":"reg","label":"20 C.F.R. § 404.950","url":"https://www.ecfr.gov/current/title-20/section-404.950","subs":["(a)","(b)","(e)"],"by":{"0":"7, 7, 8"}},{"t":"reg","label":"20 C.F.R. § 404.975","url":"https://www.ecfr.gov/current/title-20/section-404.975","by":{"0":"7"}},{"t":"reg","label":"20 C.F.R. § 404.976","url":"https://www.ecfr.gov/current/title-20/section-404.976","subs":["(c)"],"by":{"0":"7"}},{"t":"reg","label":"20 C.F.R. § 404.1512","url":"https://www.ecfr.gov/current/title-20/section-404.1512","subs":["(a)(1)","(b)"],"by":{"0":"36, 26"}},{"t":"reg","label":"20 C.F.R. § 416.912","url":"https://www.ecfr.gov/current/title-20/section-416.912","subs":["(a)(1)","(b)"],"by":{"0":"36, 26"}},{"t":"reg","label":"20 C.F.R. § 416.1400","url":"https://www.ecfr.gov/current/title-20/section-416.1400","subs":["(a)(6)","(b)"],"by":{"0":"6, 39, 6, 7"}},{"t":"reg","label":"20 C.F.R. § 416.1433","url":"https://www.ecfr.gov/current/title-20/section-416.1433","subs":["(a)"],"by":{"0":"7"}},{"t":"reg","label":"20 C.F.R. § 416.1438","url":"https://www.ecfr.gov/current/title-20/section-416.1438","subs":["(b)(1)"],"by":{"0":"26"}},{"t":"reg","label":"20 C.F.R. § 416.1439","url":"https://www.ecfr.gov/current/title-20/section-416.1439","by":{"0":"26"}},{"t":"reg","label":"20 C.F.R. § 416.1444","url":"https://www.ecfr.gov/current/title-20/section-416.1444","by":{"0":"7, 26"}},{"t":"reg","label":"20 C.F.R. § 416.1446","url":"https://www.ecfr.gov/current/title-20/section-416.1446","subs":["(a)"],"by":{"0":"7, 26, 26"}},{"t":"reg","label":"20 C.F.R. § 416.1449","url":"https://www.ecfr.gov/current/title-20/section-416.1449","by":{"0":"7, 26"}},{"t":"reg","label":"20 C.F.R. § 416.1450","url":"https://www.ecfr.gov/current/title-20/section-416.1450","subs":["(a)","(b)","(e)"],"by":{"0":"7, 7, 8"}},{"t":"reg","label":"20 C.F.R. § 416.1475","url":"https://www.ecfr.gov/current/title-20/section-416.1475","by":{"0":"7"}},{"t":"reg","label":"20 C.F.R. § 416.1476","url":"https://www.ecfr.gov/current/title-20/section-416.1476","subs":["(c)"],"by":{"0":"7"}},{"t":"reg","label":"20 C.F.R. § 422.203","url":"https://www.ecfr.gov/current/title-20/section-422.203","subs":["(b)"],"by":{"0":"26"}},{"t":"reg","label":"20 C.F.R. § 498.215-498","url":"https://www.ecfr.gov/current/title-20/section-498.215-498","by":{"0":"23"}},{"t":"reg","label":"20 C.F.R. § 498.221","url":"https://www.ecfr.gov/current/title-20/section-498.221","subs":["(f)"],"by":{"0":"24"}},{"t":"reg","label":"Executive Order 13,843, 83 Fed. Reg. 32,756","url":"https://www.govinfo.gov/link/fr/83/32756","by":{"0":"10"}},{"t":"reg","label":"84 Fed. Reg. 9,583","url":"https://www.govinfo.gov/link/fr/84/9583","by":{"0":"10, 11, 28, 45"}},{"t":"reg","label":"84 Fed. Reg. 40,468","url":"https://www.govinfo.gov/link/fr/84/40468","by":{"0":"7, 27"}},{"t":"reg","label":"85 Fed. Reg. 73,138","url":"https://www.govinfo.gov/link/fr/85/73138","by":{"0":"8, 25","1":"6, 24, 25, 31"}},{"t":"case","label":"Burnet v. Commonwealth Improvement Co.","cite":"287 U.S. 415","y":1932,"id":"scdb/1932-021","sc":1,"sum":"The record-fails to disclose circumstances sufficient to require disregard of the corporate form. P. 419. 57 F. (2d) 47, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34","2":"12"}},{"t":"case","label":"Canonsburg Gen. Hosp. v. Burwell","cite":"807 F.3d 295","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/807/295/","by":{"1":"36"}},{"t":"case","label":"Cirko ex rel. Cirko v. Comm’r, SSA","cite":"948 F.3d 148","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/948/148/","op":1,"by":{"1":"21","2":"31"}},{"t":"case","label":"Darby v. Cisneros","cite":"509 U.S. 137","y":1993,"id":"1992/91-2045","sc":1,"sum":"Federal courts do not have the authority to require a plaintiff to exhaust available administrative remedies before seeking judicial review under the APA, where neither the relevant statute nor agency rules specifically mandate exhaustion as a prerequisite to judicial review. The language of § 10(c) of the APA is explicit that an appeal to \"superior agency authority\" is a prerequisite to judicial review only when …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20","4":"12"}},{"t":"case","label":"Davis v. Saul","cite":"963 F.3d 790","y":2020,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/963/790/","op":1,"by":{"1":"42"}},{"t":"case","label":"Fandino v. Sec. of Health and Hum. Servs.","cite":"1987 WL 16150","y":1987,"court":"S.D.N.Y. Aug. 21","by":{"1":"41"}},{"t":"case","label":"Fed. Power Comm’n v. Colo. Interstate Gas Co.","cite":"348 U.S. 492","y":1955,"id":"scdb/1954-047","sc":1,"by":{"1":"33"}},{"t":"case","label":"Lucia v. SEC","cite":"138 S. Ct. 736","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/736/","sc":1,"by":{"1":"7"}},{"t":"case","label":"Marx v. Gen. Rev. Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"ar":1,"sum":"The Court held that the Federal Rules of Civil Procedure awards costs to the prevailing party unless a statute explicitly states otherwise.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"McKart v. United States","cite":"395 U.S. 185","y":1969,"id":"1968/403","sc":1,"sum":"Petitioner had been classified IV-A (sole surviving son status). When the Selective Service Board learned of the death of petitioner's mother, it reclassified him I-A (available for military service), on the theory that the IV-A classification became improper when the \"family unit\" ceased to exist. Petitioner did not appeal the reclassification. Upon his failure to report as ordered for his pre-induction physical …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27","2":"14"}},{"t":"case","label":"Morgan Stanley Cap. Grp. Inc. v. Pub. Util. Dist. No. 1","cite":"554 U.S. 527","y":2008,"id":"2007/06-1457","sc":1,"sum":"Renegotiation is allowed only if the contract poses \"serious harm to the public interest.\" In this case, the Court decided 5-2 (Justices John G. Roberts and Stephen Breyer took no part in the decision) that the Federal Energy Regulatory Commission had failed to make sufficient factual findings in order to determine whether such serious harm could in fact occur.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"N.L.R.B. v. Wyman-Gordon Co.","cite":"394 U.S. 759","y":1969,"id":"1968/463","sc":1,"sum":"The judgment of the Court of Appeals is reversed and the case is remanded to the District Court with directions to reinstate its judgment. Pp. 761-775. 397 F. 2d 394, reversed and remanded. MR. JUSTICE FORTAS, joined by THE CHIEF JUSTICE, MR. JUSTICE STEWART, and MR. JUSTICE WHITE, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"36"}},{"t":"case","label":"O’Leary v. Office of Pers. Mgmt.","cite":"708 F. App’x 669","y":2017,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/708/669/","by":{"1":"7"}},{"t":"case","label":"Probst v. Saul","cite":"980 F.3d 1015","y":2020,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/980/1015/","op":1,"by":{"1":"21","2":"31"}},{"t":"case","label":"Ramsey v. Comm’r, SSA","cite":"973 F.3d 537","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/973/537/","op":1,"by":{"1":"21","2":"31"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"Sung v. McGrath","cite":"339 U.S. 33","y":1950,"id":"scdb/1949-048","sc":1,"sum":"This was contrary to the purpose of the Administrative Procedure Act to ameliorate the evils resulting from a combination of the prosecuting and adjudicating functions in administrative proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"34","2":"26","3":"14"}},{"t":"usc","label":"15 U.S.C. § 78y","url":"https://www.law.cornell.edu/uscode/text/15/78y","subs":["(c)","(c)(1)"],"stext":{"head":"§78y. Court review of orders and rules","paras":[[0,"(a) Final Commission orders; persons aggrieved; petition; record; findings; affirmance, modification, enforcement, or setting aside of orders; remand to adduce additional evidence"],[0,"(1) A person aggrieved by a final order of the Commission entered pursuant to this chapter may obtain review of the order in the United States Court of Appeals for the circuit in which he resides or has his principal place of business, or for the District of Columbia Circuit, by filing in such court, within sixty days after the entry of the order, a written petition requesting that the order be modified or set aside in whole or in part."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated by the Commission for that purpose. Thereupon the Commission shall file in the court the record on which the order complained of is entered, as provided in section 2112 of title 28 and the Federal Rules of Appellate Procedure."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the record, to affirm or modify and enforce or to set aside the order in whole or in part."],[0,"(4) The findings of the Commission as to the facts, if supported by substantial evidence, are conclusive."],[0,"(5) If either party applies to the court for leave to adduce additional evidence and shows to the satisfaction of the court that the additional evidence is material and that there was reasonable ground for failure to adduce it before the Commission, the court may remand the case to the Commission for further proceedings, in whatever manner and on whatever conditions the court considers appropriate. If the case is remanded to the Commission, it shall file in the court a supplemental record containing any new evidence, any further or modified findings, and any new order."],[0,"(b) Commission rules; persons adversely affected; petition; record; affirmance, enforcement, or setting aside of rules; findings; transfer of proceedings"],[0,"(1) A person adversely affected by a rule of the Commission promulgated pursuant to section 78f, 78i(h)(2), 78k, 78k–1, 78o(c)(5) or (6), 78o–3, 78q, 78q–1, or 78s of this title may obtain review of this rule in the United States Court of Appeals for the circuit in which he resides or has his principal place of business or for the District of Columbia Circuit, by filing in such court, within sixty days after the promulgation of the rule, a written petition requesting that the rule be set aside."],[0,"(2) A copy of the petition shall be transmitted forthwith by the clerk of the court to a member of the Commission or an officer designated for that purpose. Thereupon, the Commission shall file in the court the rule under review and any documents referred to therein, the Commission's notice of proposed rulemaking and any documents referred to therein, all written submissions and the transcript of any oral presentations in the rulemaking, factual information not included in the foregoing that was considered by the Commission in the promulgation of the rule or proffered by the Commission as pertinent to the rule, the report of any advisory committee received or considered by the Commission in the rulemaking, and any other materials prescribed by the court."],[0,"(3) On the filing of the petition, the court has jurisdiction, which becomes exclusive on the filing of the materials set forth in paragraph (2) of this subsection, to affirm and enforce or to set aside the rule."],[0,"(4) The findings of the Commission as to the facts identified by the Commission as the basis, in whole or in part, of the rule, if supported by substantial evidence, are conclusive. The court shall affirm and enforce the rule unless the Commission's action in promulgating the rule is found to be arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law; contrary to constitutional right, power, privilege, or immunity; in excess of statutory jurisdiction, authority, or limitations, or short of statutory right; or without observance of procedure required by law."],[0,"(5) If proceedings have been instituted under this subsection in two or more courts of appeals with respect to the same rule, the Commission shall file the materials set forth in paragraph (2) of this subsection in that court in which a proceeding was first instituted. The other courts shall thereupon transfer all such proceedings to the court in which the materials have been filed. For the convenience of the parties in the interest of justice that court may thereafter transfer all the proceedings to any other court of appeals."],[0,"(c) Objections not urged before Commission; stay of orders and rules; transfer of enforcement or review proceedings"],[0,"(1) No objection to an order or rule of the Commission, for which review is sought under this section, may be considered by the court unless it was urged before the Commission or there was reasonable ground for failure to do so."],[0,"(2) The filing of a petition under this section does not operate as a stay of the Commission's order or rule. Until the court's jurisdiction becomes exclusive, the Commission may stay its order or rule pending judicial review if it finds that justice so requires. After the filing of a petition under this section, the court, on whatever conditions may be required and to the extent necessary to prevent irreparable injury, may issue all necessary and appropriate process to stay the order or rule or to preserve status or rights pending its review; but (notwithstanding section 705 of title 5) no such process may be issued by the court before the filing of the record or the materials set forth in subsection (b)(2) of this section unless: (A) the Commission has denied a stay or failed to grant requested relief, (B) a reasonable period has expired since the filing of an application for a stay without a decision by the Commission, or (C) there was reasonable ground for failure to apply to the Commission."],[0,"(3) When the same order or rule is the subject of one or more petitions for review filed under this section and an action for enforcement filed in a district court of the United States under section 78u(d) or (e) of this title, that court in which the petition or the action is first filed has jurisdiction with respect to the order or rule to the exclusion of any other court, and thereupon all such proceedings shall be transferred to that court; but, for the convenience of the parties in the interest of justice, that court may thereafter transfer all the proceedings to any other court of appeals or district court of the United States, whether or not a petition for review or an action for enforcement was originally filed in the transferee court. The scope of review by a district court under section 78u(d) or (e) of this title is in all cases the same as by a court of appeals under this section."],[0,"(d) Other appropriate regulatory agencies"],[0,"(1) For purposes of the preceding subsections of this section, the term \"Commission\" includes the agencies enumerated in section 78c(a)(34) of this title insofar as such agencies are acting pursuant to this chapter and the Secretary of the Treasury insofar as he is acting pursuant to section 78o–5 of this title."],[0,"(2) For purposes of subsection (a)(4) of this section and section 706 of title 5, an order of the Commission pursuant to section 78s(a) of this title denying registration to a clearing agency for which the Commission is not the appropriate regulatory agency or pursuant to section 78s(b) of this title disapproving a proposed rule change by such a clearing agency shall be deemed to be an order of the appropriate regulatory agency for such clearing agency insofar as such order was entered by reason of a determination by such appropriate regulatory agency pursuant to section 78s(a)(2)(C) or 78s(b)(4)(C) of this title that such registration or proposed rule change would be inconsistent with the safeguarding of securities or funds."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78y?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§78y. Court review of orders and rules","tname":"Commerce and Trade","by":{"1":"19, 35","4":"19"}},{"t":"usc","label":"21 U.S.C. § 355","url":"https://www.law.cornell.edu/uscode/text/21/355","subs":["(h)"],"by":{"1":"19"}},{"t":"usc","label":"25 U.S.C. § 4161","url":"https://www.law.cornell.edu/uscode/text/25/4161","subs":["(d)(2)"],"by":{"1":"19"}},{"t":"usc","label":"27 U.S.C. § 204","url":"https://www.law.cornell.edu/uscode/text/27/204","subs":["(h)"],"by":{"1":"19"}},{"t":"usc","label":"28 U.S.C. § 636","url":"https://www.law.cornell.edu/uscode/text/28/636","subs":["(c)(1)"],"by":{"1":"1"}},{"t":"reg","label":"10 C.F.R. § 2.341","url":"https://www.ecfr.gov/current/title-10/section-2.341","subs":["(a)(1)"],"by":{"1":"21"}},{"t":"reg","label":"12 C.F.R. § 308.39","url":"https://www.ecfr.gov/current/title-12/section-308.39","subs":["(b)"],"by":{"1":"21"}},{"t":"reg","label":"16 C.F.R. § 3.52","url":"https://www.ecfr.gov/current/title-16/section-3.52","subs":["(c)"],"by":{"1":"21"}},{"t":"reg","label":"20 C.F.R. § 404.603","url":"https://www.ecfr.gov/current/title-20/section-404.603","by":{"1":"5"}},{"t":"reg","label":"20 C.F.R. § 404.929","url":"https://www.ecfr.gov/current/title-20/section-404.929","by":{"1":"5"}},{"t":"reg","label":"28 C.F.R. § 542.15","url":"https://www.ecfr.gov/current/title-28/section-542.15","subs":["(b)(2)"],"by":{"1":"21"}},{"t":"reg","label":"38 C.F.R. § 20.202","url":"https://www.ecfr.gov/current/title-38/section-20.202","subs":["(a)"],"by":{"1":"21"}},{"t":"reg","label":"Amendments to the Administrative Law Judge, Appeals Council, and Decision Review Board Appeals Levels, 72 Fed. Reg. 61,218","url":"https://www.govinfo.gov/link/fr/72/61218","by":{"1":"22, 23"}},{"t":"reg","label":"Page Miscellaneous—continued: Excepting Administrative Law Judges From the Competitive Service, 83 Fed. Reg. 32,755","url":"https://www.govinfo.gov/link/fr/83/32755","by":{"1":"7, 9"}},{"t":"reg","label":"Hearings, Appeals, and Judicial Review Under Titles II, and XVIII of the Social Security Act, 41 Fed. Reg. 51,585","url":"https://www.govinfo.gov/link/fr/41/51585","by":{"1":"23"}},{"t":"case","label":"Anderson v. Barnhart","cite":"344 F.3d 809","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/344/809/","by":{"2":"30, 33","3":"19","4":"14"}},{"t":"case","label":"Bandimere v. SEC","cite":"844 F.3d 1168","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/844/1168/","by":{"2":"5"}},{"t":"case","label":"Bolling v. Lersner","cite":"91 U.S. 594","y":1876,"id":"scdb/1875-070","sc":1,"sum":"This court has no jurisdiction to re-examine the judgment or decree of a State. court, unless it.appears-from the record that a Federal question presented to that\" court was in fact decided, or that the decision was necessarily involved in the judgmefit or decree as rendered.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"Brewer v. Chater","cite":"103 F.3d 1384","y":1997,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/103/1384/","by":{"2":"30","3":"19"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Dalton Adding Machine Co. v. State Corp. Comm’n","cite":"236 U.S. 699","y":1915,"id":"scdb/1914-187","sc":1,"sum":"The rule that courts should not stop state officers charged with enforcing laws from performing their statutory duty for fear they should perform it wrongly applies especially in cases of taxes and license fees.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"41","3":"10"}},{"t":"case","label":"Edmond v. United States","cite":"520 U.S. 651","y":1997,"id":"1996/96-262","sc":1,"sum":"The Court held that the judicial appointments were valid. The Court unanimously found that Congress has authorized the Secretary to appoint civilian members of the Coast Guard Court of Criminal Appeals.","sumSrc":"Oyez","by":{"2":"44"}},{"t":"case","label":"Erie R.R. v. Tompkins","cite":"304 U.S. 64","y":1938,"id":"1900-1940/304us64","sc":1,"sum":"A case in which the Court overturned its prior decision in Swift v. Tyson and held that federal courts exercising diversity jurisdiction cannot create their own common law for issues that properly fall within state law.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"FCC v. Pottsville Broad. Co.","cite":"309 U.S. 134","y":1940,"id":"scdb/1939-099","sc":1,"op":1,"sum":"1. A lower court's interpretation of its own mandate does not bind this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Federal Maritime Commission v. South Carolina State Ports Authority","cite":"535 U.S. 743","y":2002,"id":"2001/01-46","sc":1,"sum":"The Court held that state sovereign immunity bars the FMC from adjudicating a private party's complaint against a nonconsenting State. Historically, the Court noted, states were not subject to private suits in administrative adjudications when the Constitution was adopted, and states were thus presumptively immune from such actions.","sumSrc":"Oyez","by":{"2":"13, 25","4":"10"}},{"t":"case","label":"Florida Power & Light Co. v. Lorion","cite":"470 U.S. 729","y":1985,"id":"1984/83-703","sc":1,"sum":"Section 2239 vests in the courts of appeals initial subject-matter jurisdiction over Commission orders denying citizen petitions made pursuant to Commission rules.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Gagliardi v. Social Sec. Admin.","cite":"441 F. Supp. 3d 1284","y":2020,"court":"S.D. Fla.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/441/1284/","by":{"2":"31"}},{"t":"case","label":"General Utilities & Operating Co. v. Helvering","cite":"296 U.S. 200","y":1935,"id":"scdb/1935-029","sc":1,"by":{"2":"12"}},{"t":"case","label":"Gonzalez-Ayala v. Secretary of Health & Human Servs.","cite":"807 F.2d 255","y":1986,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/807/255/","by":{"2":"31","4":"14"}},{"t":"case","label":"Heckler v. Campbell","cite":"461 U.S. 458","y":1983,"id":"1982/81-1983","sc":1,"sum":"The Secretary's use of the medical-vocational guidelines to determine a claimant's right to disability benefits does not conflict with the Social Security Act, nor are the guidelines arbitrary or capricious.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Helvering v. Pfeiffer","cite":"302 U.S. 247","y":1937,"id":"scdb/1937-031","sc":1,"sum":"1. Section 115 (f) of the. Revenue Act 1928 exempted dividends of preferred stock from taxation. Helvering v. Gowran, ante, p. 238.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12","3":"14"}},{"t":"case","label":"Helvering v. Salvage","cite":"297 U.S. 106","y":1936,"id":"scdb/1935-074","sc":1,"sum":"Assistant Solicitor General Bell, with whom Solicitor General Reed, Assistant Attorney General Wideman and Mr. John R. Benney were on the brief, for the Commissioner.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Hulsey v. Saul","cite":"794 Fed. Appx. 659","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./794/659/","by":{"2":"31"}},{"t":"case","label":"Jones Bros. v. Secretary of Labor","cite":"898 F.3d 669","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/898/669/","by":{"2":"41"}},{"t":"case","label":"Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"sum":"The Court held that Kontrick lost the right to invoke Rule 4004's time limitation because he did so after the bankruptcy court reached the merits of Ryan's objection. The Court rejected Kontrick's claim that Rule 4004 is \"jurisdictional\" and that it trumps other considerations whenever raised in proceedings.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"Krysztoforski v. Chater","cite":"55 F.3d 857","y":1995,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/55/857/","by":{"2":"30"}},{"t":"case","label":"Mapp v. Ohio","cite":"367 U.S. 643","y":1961,"id":"1960/236","sc":1,"sum":"The Court decided that evidence obtained illegally may not be used against someone in a court of law by the Fourth Amendment.","sumSrc":"Oyez","by":{"2":"48"}},{"t":"case","label":"Meanel v. Apfel","cite":"172 F.3d 1111","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/172/1111/","by":{"2":"30, 31","3":"19","4":"14"}},{"t":"case","label":"Mills v. Apfel","cite":"244 F.3d 1","y":2001,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/244/1/","by":{"2":"33, 34, 36"}},{"t":"case","label":"North Carolina v. Covington","cite":"137 S. Ct. 1624","y":2017,"id":"2016/16-1023","sc":1,"sum":"The Court determined that ordering equitable relief in a redistricting case requires that a court consider the severity and nature of the constitutional violation, the extent of the likely disruption to the ordinary processes of governance if early elections are imposed, and the need to act with proper judicial restraint when intruding on state sovereignty.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Norton v. Shelby County","cite":"118 U.S. 425","y":1886,"id":"scdb/1885-275","sc":1,"ar":1,"sum":"This court follows the decisions of the highest court of a State, in construing the Constitution and laws of the State, unless they conflict with or impair the efficacy of some principle of the Federal Constitution, or of a Federal statute, or a rule of commercial or general law.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"15, 16"}},{"t":"case","label":"Phillips v. Payne","cite":"92 U.S. 130","y":1876,"id":"scdb/1875-159","sc":1,"by":{"2":"15"}},{"t":"case","label":"Renegotiation Bd. v. Bannercraft Clothing Co.","cite":"415 U.S. 1","y":1974,"id":"1973/72-822","sc":1,"sum":"Respondents, whose profits on defense contracts are undergoing renegotiation pursuant to the Renegotiation Act of 1951, sued in the District Court under the Freedom of Information Act (FOIA) to enjoin petitioner Board from withholding documents that respondents had requested and from conducting any further renegotiation proceedings until the documents were produced. The District Court in each case granted injunctive …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"41","3":"10"}},{"t":"case","label":"Republic of Argentina v. NML Capital, Ltd.","cite":"573 U.S. 134","y":2014,"id":"2013/12-842","sc":1,"sum":"The Court held that, under the Foreign Sovereign Immunities Act, property held within the US by foreign nations cannot be attached to civil claims unless certain exceptions are met.","sumSrc":"Oyez","by":{"2":"27"}},{"t":"case","label":"Ryder v. United States","cite":"515 U.S. 177","y":1995,"id":"1994/94-431","sc":1,"op":4,"ar":6,"sum":"The Court held that the judges' actions were not valid de facto. The Court reasoned that a defendant who made a timely challenge to the constitutional validity of the appointment of an officer who adjudicates his case was entitled to a decision on the merits of the question and whatever relief may be appropriate if a violation had occurred.","sumSrc":"Oyez","by":{"2":"9, 16, 18","3":"15, 16, 17","4":"18, 19, 20"}},{"t":"case","label":"Shaibi v. Berryhill","cite":"883 F.3d 1102","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/1102/","by":{"2":"33","3":"19"}},{"t":"case","label":"Shapiro v. Saul","cite":"2021 WL 164917","y":2021,"court":"9th Cir. Jan. 19","by":{"2":"30"}},{"t":"case","label":"Sullivan v. Commissioner of Social Security","cite":"694 Fed. Appx. 670","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./694/670/","by":{"2":"30","4":"14"}},{"t":"case","label":"Tesoro Refining & Marketing Co. v. FERC","cite":"552 F.3d 868","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/552/868/","by":{"2":"45, 46"}},{"t":"case","label":"Union Pac. R.R. v. Brotherhood of Locomotive Engineers & Trainmen","cite":"558 U.S. 67","y":2009,"id":"2009/08-604","sc":1,"sum":"A case in which the Court further held that pre-arbitration settlement conferences are not a prerequisite for National Railroad Adjustment Board jurisdiction over a dispute.","sumSrc":"Oyez","by":{"2":"40"}},{"t":"case","label":"United States v. Atkinson","cite":"297 U.S. 157","y":1936,"id":"scdb/1935-082","sc":1,"sum":"In the absence of exceptional circumstances, error in a jury trial, which was not brought to the attention of the court by proper exception or request to charge, will not be considered on appeal. P. 159. 76 F. (2d) 564, affirmed. CERTIORARI, 296 U. S. 559, to review a judgment affirming a judgment against the United States in an action on a policy of converted war risk insurance. Mr. Will G. Beardslee, with whom …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"United States v. Burr","cite":"25 F. Cas. 30","y":1807,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./25/30/","by":{"2":"46"}},{"t":"case","label":"United States v. Germaine","cite":"99 U.S. 508","y":1879,"id":"scdb/1878-198","sc":1,"sum":"1. Civil surgeons appointed by the Commissioner of Pensions under sect. 4777 of the Revised Statutes are not officers of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"United States v. Illinois Central R.R.","cite":"291 U.S. 457","y":1934,"id":"scdb/1933-161","sc":1,"sum":"Assistant Solicitor General MacLean, with whom Solicitor General Biggs, Assistant Attorney General Stephens, and Messrs. Elmer B. Collins, Ashley Sellers, Daniel W. Knowlton, and Harry L. Underwood were on the brief, for the United States and Interstate Commerce Commission, appellants.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"41","3":"10"}},{"t":"case","label":"United States v. Williams","cite":"504 U.S. 36","y":1992,"id":"1991/90-1972","sc":1,"sum":"Respondent Williams was indicted by a federal grand jury for alleged violations of 18 U. S. C. § 1014. On his motion, the District Court ordered the indictment dismissed without prejudice because the Government had failed to fulfill its obligation under Circuit precedent to present \"substantial exculpatory evidence\" to the grand jury. Following that precedent, the Court of Appeals affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"Wainwright v. Sykes","cite":"433 U.S. 72","y":1977,"id":"1976/75-1578","sc":1,"sum":"Respondent's failure to make timely objection under the Florida contemporaneous-objection rule to the admission of his inculpatory statements, absent a showing of cause for the noncompliance and some showing of actual prejudice, bars federal habeas corpus review of his Miranda claim. Davis v. United States, 411 U. S. 233; Francis v. Henderson,425 U. S. 536.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"27"}},{"t":"case","label":"White v. Johnson","cite":"282 U.S. 367","y":1931,"id":"scdb/1930-116","sc":1,"by":{"2":"41","3":"10"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"2":"2"}},{"t":"usc","label":"42 U.S.C. § 1381","url":"https://www.law.cornell.edu/uscode/text/42/1381","by":{"2":"3, 7"}},{"t":"usc","label":"42 U.S.C. § 1383","url":"https://www.law.cornell.edu/uscode/text/42/1383","by":{"2":"3"}},{"t":"rule","label":"Fed. R. Crim. P. 51","url":"https://www.law.cornell.edu/rules/frcrmp/rule_51","by":{"2":"28"}},{"t":"case","label":"Bond v. United States","cite":"564 U.S. 211","y":2011,"id":"2010/09-1227","sc":1,"sum":"The Court held that a defendant, convicted under a federal statute, has a right to challenge his/her conviction based on the unconstitutionality of the statute.","sumSrc":"Oyez","by":{"3":"22"}},{"t":"case","label":"Glidden Co. v. Zdanok","cite":"370 U.S. 530","y":1962,"id":"1961/242","sc":1,"sum":"The Court held that judges in the United States Court of Claims and the United States Court of Customs and Patent Appeals constitutionally protected in tenure and compensation under Article III of the Constitution.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Sullivan v. Comm’r of Soc. Sec.","cite":"694 F. App’x 670","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/694/670/","by":{"3":"19"}},{"t":"case","label":"Unemployment Comp. Comm’n of Alaska v. Aragon","cite":"329 U.S 143","y":1946,"url":"https://www.courtlistener.com/c/U.S/329/143/","by":{"3":"14"}},{"t":"case","label":"United States v. Gladue","cite":"67 M.J. 311","y":2009,"court":"C.A.A.F.","url":"https://www.courtlistener.com/c/M.J./67/311/","op":1,"by":{"3":"17"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"3":"11"}},{"t":"case","label":"Dietz v. Bouldin","cite":"136 S. Ct. 1885","y":2016,"id":"2015/15-458","sc":1,"sum":"The Court determined that a federal district court judge has some ability to recall jurors in a civil case after identifying an error in their verdict, subject to certain limitations to ensure the jurors were not prejudiced.","sumSrc":"Oyez","by":{"4":"12"}},{"t":"case","label":"Moses H. Cone Memorial Hospital v. Mercury Construction Corp.","cite":"460 U.S. 1","y":1983,"id":"1982/81-1203","sc":1,"sum":"Petitioner, a hospital located in North Carolina, entered into a contract with respondent contractor, an Alabama corporation, for construction of additions to the hospital building. Contract disputes were to be initially referred to the architect who was hired to design and oversee the construction project. Disputes decided by the architect or not decided within a specified time could be submitted to binding …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"4"}},{"t":"case","label":"(I) Cases—continued: Ortiz v. United States","cite":"138 S. Ct. 2165","y":2018,"id":"2017/16-1423","sc":1,"ar":1,"sum":"The Court held that it has jurisdiction to review the CAAF's decisions and that Judge Martin T. Mitchell’s simultaneous service on the US Court of Military Commission Review (CMCR) and the US Air Force Court of Criminal Appeals (AFCCA) does not violate the Appointments Clause or 10 U.S.C. § 973(b)(2)(A).","sumSrc":"Oyez","by":{"4":"19"}},{"t":"case","label":"Seila Law LLC v. Consumer Financial Protection Bureau","cite":"140 S. Ct. 2183","y":2020,"id":"2019/19-7","sc":1,"ar":1,"sum":"The Court held that the vesting of substantial executive authority in the Consumer Financial Protection Bureau, an independent agency led by a single director, violates the separation of powers, but the statutory provision creating that violation, 12 U.S.C. § 5491(c)(3) is severable from the Dodd-Frank Act.","sumSrc":"Oyez","by":{"4":"20, 21"}},{"t":"case","label":"Seminole Tribe of Florida v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"4":"5"}},{"t":"case","label":"Shapiro v. Saul","cite":"833 Fed. Appx. 695","y":2021,"court":"9th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./833/695/","by":{"4":"14"}},{"t":"case","label":"United States v. Greene","cite":"41 M.J. 57","y":1994,"court":"C.M.A.","url":"https://www.courtlistener.com/c/M.J./41/57/","by":{"4":"19"}},{"t":"reg","label":"20 C.F.R. § 404.935","url":"https://www.ecfr.gov/current/title-20/section-404.935","subs":["(a)"],"by":{"4":"8"}},{"t":"reg","label":"20 C.F.R. § 404.967","url":"https://www.ecfr.gov/current/title-20/section-404.967","by":{"4":"8"}},{"t":"reg","label":"20 C.F.R. § 404.981","url":"https://www.ecfr.gov/current/title-20/section-404.981","by":{"4":"18"}},{"t":"reg","label":"20 C.F.R. § 404.985","url":"https://www.ecfr.gov/current/title-20/section-404.985","by":{"4":"6"}},{"t":"reg","label":"55 Fed. Reg. 1,012","url":"https://www.govinfo.gov/link/fr/55/1012","by":{"4":"6"}},{"t":"reg","label":"84 Fed. Reg. 9,582","url":"https://www.govinfo.gov/link/fr/84/9582","by":{"4":"16"}}]};